module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

    parameter IDLE  = 3'b000;
    parameter S1    = 3'b001;
    parameter S2    = 3'b010;
    parameter S3    = 3'b011;
    parameter S4    = 3'b100;
    parameter S5    = 3'b101;

    reg [2:0] current_state, next_state;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            IDLE: next_state = IN ? S1 : IDLE;
            S1:   next_state = IN ? S1 : S2;
            S2:   next_state = IN ? S1 : S3;
            S3:   next_state = IN ? S4 : S3;
            S4:   next_state = IN ? S5 : IDLE;
            S5:   next_state = IN ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end


    always @(*) begin
        MATCH = (current_state == S4) && IN;
    end

endmodule

