module asyn_fifo #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
) (
  input wire wclk,
  input wire wrstn,
  input wire winc,
  input wire [WIDTH-1:0] wdata,

  input wire rclk,
  input wire rrstn,
  input wire rinc,

  output wire wfull,
  output wire rempty,
  output wire [WIDTH-1:0] rdata
);

  localparam ADDR_WIDTH = $clog2(DEPTH);
  localparam PTR_WIDTH = ADDR_WIDTH + 1;


  dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
  ) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),

    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
  );


  reg [PTR_WIDTH-1:0] waddr_bin;

  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) waddr_bin <= 0;
    else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
  end

  wire [PTR_WIDTH-1:0] waddr_gray = (waddr_bin >> 1) ^ waddr_bin;


  reg [PTR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync;

  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      raddr_gray_sync1 <= 0;
      raddr_gray_sync <= 0;
    end else begin
      raddr_gray_sync1 <= raddr_gray;
      raddr_gray_sync <= raddr_gray_sync1;
    end
  end


  wire full_gray_condition = (waddr_gray == {~raddr_gray_sync[PTR_WIDTH-1:PTR_WIDTH-2], raddr_gray_sync[PTR_WIDTH-3:0]});
  reg wfull_reg;

  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull_reg <= 0;
    else wfull_reg <= full_gray_condition;
  end

  assign wfull = wfull_reg;


  reg [PTR_WIDTH-1:0] raddr_bin;

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) raddr_bin <= 0;
    else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
  end

  wire [PTR_WIDTH-1:0] raddr_gray = (raddr_bin >> 1) ^ raddr_bin;


  reg [PTR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync;

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      waddr_gray_sync1 <= 0;
      waddr_gray_sync <= 0;
    end else begin
      waddr_gray_sync1 <= waddr_gray;
      waddr_gray_sync <= waddr_gray_sync1;
    end
  end


  reg rempty_reg;

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty_reg <= 1;
    else rempty_reg <= (raddr_gray == waddr_gray_sync);
  end

  assign rempty = rempty_reg;

endmodule

