module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [3:0] shift_reg;
reg [1:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        cnt <= 2'b0;
        valid_out <= 0;
        dout <= 0;
    end else begin
        if (cnt == 2'b11) begin
            shift_reg <= d;
            cnt <= 2'b00;
