module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s3_green = 2'b10;
    parameter s2_yellow = 2'b11;

    reg [1:0] state;
    reg [1:0] prev_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow: if (cnt == 0) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) prev_state <= idle;
        else prev_state <= state;
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state != prev_state) begin
                case (state)
                    s1_red: cnt <= 10;
                    s3_green: cnt <= 60;
                    s2_yellow: cnt <= 5;
                    default: cnt <= 10;
                endcase
            end else begin
                if (cnt == 0) cnt <= 0;
                else cnt <= cnt - 1;
            end

            if (pass_request && (state == s3_green)) begin
                if (cnt > 10) cnt <= 10;
            end
        end
    end


    always @(*) begin
        case (state)
            s1_red: {p_red, p_yellow, p_green} = 3'b100;
            s3_green: {p_red, p_yellow, p_green} = 3'b001;
            s2_yellow: {p_red, p_yellow, p_green} = 3'b010;
            default: {p_red, p_yellow, p_green} = 3'b000;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end


    always @(*) clock = cnt;

endmodule

