module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;
reg state;

localparam STATE_IDLE = 0;
localparam STATE_RISE = 1;
localparam STATE_FALL = 2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 0;
        state <= STATE_IDLE;
        rise <= 0;
        down <= 0;
    end else begin
        a_prev <= a;
        case (state)
            STATE_IDLE: begin
                rise <= 0;
                down <= 0;
                if (a_prev && !a) begin         
                    down <= 1;
                    state <= STATE_FALL;
                end else if (!a_prev && a) begin 
                    rise <= 1;
                    state <= STATE_RISE;
                end
            end
            STATE_RISE: begin
                if (a_prev && !a) begin         
                    down <= 1;
                    rise <= 0;
                    state <= STATE_FALL;
                end else begin
                    rise <= 1;

                end
            end
            STATE_FALL: begin
                if (!a_prev && a) begin         
                    rise <= 1;
                    down <= 0;
                    state <= STATE_RISE;
                end else begin
                    down <= 1;

                end
            end
            default: state <= STATE_IDLE;
        endcase
    end
end

endmodule

