module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] shift_reg;

reg [7:0] saved_dividend_abs;
reg [7:0] saved_divisor_abs;
reg [3:0] cnt;

reg dividend_sign, divisor_sign;
reg state;

localparam IDLE = 0;
localparam DIVIDING = 1;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        shift_reg <= 0;
        cnt <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    dividend_sign <= sign ? dividend[7] : 1'b0;
                    divisor_sign <= sign ? divisor[7] : 1'b0;
                    saved_dividend_abs <= sign ? ((dividend[7]) ? (~dividend + 1) : dividend) : dividend;
                    saved_divisor_abs <= sign ? ((divisor[7]) ? (~divisor + 1) : divisor) : divisor;

                    shift_reg <= {8'b0, saved_dividend_abs};
                    cnt <= 0;
                    state <= DIVIDING;
                end
            end
            DIVIDING: begin
                if (cnt < 8) begin

                    reg [8:0] temp_remainder;
                    temp_remainder = {1'b0, shift_reg[15:8]} - {1'b0, saved_divisor_abs};

                    if (temp_remainder[8]) begin 
                        shift_reg <= {temp_remainder[7:0], shift_reg[7:0] << 1 | 1'b0};
                    end else begin 
                        shift_reg <= {temp_remainder[7:0], shift_reg[7:0] << 1 | 1'b1};
                    end
                    cnt <= cnt + 1;
                end else begin

                    reg [7:0] quotient = shift_reg[7:0];
                    reg [7:0] remainder = shift_reg[15:8];
                    if (sign) begin

                        if (dividend_sign ^ divisor_sign) begin
                            quotient = ~quotient + 1;
                        end

                        if (dividend_sign) begin
                            remainder = ~remainder + 1;
                        end
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

