module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);
    wire [3:0] diff;
    wire [3:0] borrow;

    full_subtractor fs0 (
        .a(A[0]),
        .b(B[0]),
        .bin(1'b0),
        .diff(diff[0]),
        .bout(borrow[0])
    );

    full_subtractor fs1 (
        .a(A[1]),
        .b(B[1]),
        .bin(borrow[0]),
        .diff(diff[1]),
        .bout(borrow[1])
    );

    full_subtractor fs2 (
        .a(A[2]),
        .b(B[2]),
        .bin(borrow[1]),
        .diff(diff[2]),
        .bout(borrow[2])
    );

    full_subtractor fs3 (
        .a(A[3]),
        .b(B[3]),
        .bin(borrow[2]),
        .diff(diff[3]),
        .bout(borrow[3])
    );

    assign A_less = borrow[3];
    assign A_equal = (diff == 4'b0) && ~borrow[3];
    assign A_greater = (diff != 4'b0) && ~borrow[3];
