                areg <= ain;
                breg <= bin;
            end


            if (i > 0 && i < 17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end


            if (i == 16) begin
                done <= 1;
            end else if (i == 17) begin
                done <= 0;
            end
        end else begin
            i <= 0;
            done <= 0;
        end
    end
end

