    if (!rst_n) begin
        counter <= 2'b0;
        valid_out <= 0;
        data_out <= 0;
        data_reg[0] <= 0;
        data_reg[1] <= 0;
        data_reg[2] <= 0;
        data_reg[3] <= 0;
    end else begin
        valid_out <= 0;
        if (valid_in) begin
            data_reg[counter] <= data_in;
            if (counter == 2'b11) begin
                data_out <= sum_full;
                valid_out <= 1;
                counter <= 2'b0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
end

