module fixed_point_adder #(
    parameter Q = 8,   
    parameter N = 16    
) (
    input [N-1:0] a,   
    input [N-1:0] b,   
    output reg [N-1:0] c 
);

reg [N-1:0] res;

reg sign_a, sign_b;

reg [N-1:0] abs_a, abs_b;

reg [N-1:0] sum_abs;

reg [N-1:0] diff_abs;


always @(*) begin

    sign_a = a[N-1];
    sign_b = b[N-1];
    abs_a = sign_a ? -a : a;
    abs_b = sign_b ? -b : b;


    if (sign_a == sign_b) begin
        sum_abs = abs_a + abs_b;
        res = {sign_a, sum_abs[N-2:0]};

    end else begin
        if (abs_a > abs_b) begin
            diff_abs = abs_a - abs_b;
            res = {sign_a, diff_abs[N-2:0]};
        end else if (abs_b > abs_a) begin
            diff_abs = abs_b - abs_a;
            res = {sign_b, diff_abs[N-2:0]};
        end else begin 
            res = 0;
        end
    end


    c = res;
end

endmodule

