module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter = 0;
    reg [23:0] a_mant, b_mant, z_mant;
    reg [9:0] a_exp, b_exp, z_exp;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_mant <= (a_exp == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mant <= (b_exp == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 1;
                end

                1: begin

                    if (a_exp == 8'hff) begin
                        if (b_exp == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h400000};

                        end else if (b_mant == 0) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                    end else if (b_exp == 8'hff) begin
                        if (a_mant == 0) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                    end else if (a_mant == 0 || b_mant == 0) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                    end else begin
                        product <= a_mant * b_mant;
                        z_sign <= a_sign ^ b_sign;
                        counter <= 2;
                    end
                end

                2: begin

                    {guard, round, sticky} = {product[23], product[22], |product[21:0]};
                    if (product[47:46] == 2'b10 || product[47:46] == 2'b11) begin
                        z_mant <= product[46:24];
                        z_exp <= a_exp + b_exp - 107;
                        product[47:0] = product >> 1;
                        {guard, round, sticky} = {product[23], product[22], |product[21:0]};
                        counter <= 3;
                    end else begin
                        z_mant <= product[46:24];
                        z_exp <= a_exp + b_exp - 107;
                        counter <= 3;
                    end
                end

                3: begin

                    if (guard) begin
                        if (round | sticky) begin
                            z_mant <= z_mant + 1;
                        end else if (z_mant[0]) begin
                            z_mant <= z_mant + 1;
                        end
                    end


                    if (z_mant[23]) begin
                        z_mant <= 24'b0;
                        z_exp <= z_exp + 1;
                    end

                    if (z_exp[9]) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (z_exp == 0) begin
                        z <= {z_sign, 23'b0, z_mant[22:0]};

                    end else begin
                        z <= {z_sign, z_exp[7:0], z_mant[22:0]};
                    end

                    counter <= 0;
                end
            endcase
        end
    end

endmodule

