module sub_64bit (
    input signed [63:0] A,
    input signed [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

always @(*) begin
    result = A - B;
    overflow = ((A[63] == 0 && B[63] == 1 && result[63] == 1) || 
               (A[63] == 1 && B[63] == 0 && result[63] == 0)) ? 1'b1 : 1'b0;
end

