module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

reg [2:0] state;

localparam S0 = 0,
           S1 = 1,
           S2 = 2,
           S3 = 3,
           S4 = 4,
           S5 = 5;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
    end else begin
        case (state)
            S0: state <= IN ? S1 : S0;
            S1: state <= IN ? S1 : S2;
            S2: state <= IN ? S4 : S3;
            S3: state <= IN ? S4 : S0;
            S4: state <= IN ? S5 : S0;
            S5: state <= S0;
            default: state <= S0;
        endcase
    end
end

always @(*) begin
    MATCH = (state == S4 && IN);
end

endmodule

