module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    parameter S0 = 2'b00;
    parameter S1 = 2'b01;
    parameter S2 = 2'b10;

    reg [1:0] current_state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            S0: begin
                next_state = (data_in == 0) ? S1 : S0;
            end
            S1: begin
                next_state = (data_in == 1) ? S2 : S0;
            end
            S2: begin
                next_state = S0;

            end
            default: next_state = S0;
        endcase
    end


    always @(*) begin
        data_out = ((current_state == S2) && (data_in == 0)) ? 1'b1 : 1'b0;
    end

endmodule

