module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [7:0] remainder;
reg [7:0] quotient;
reg [15:0] shift_reg;
reg [3:0] cnt;
reg start_cnt;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        start_cnt <= 0;
        cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        remainder <= 0;
        quotient <= 0;
        shift_reg <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            if (sign) begin
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            shift_reg <= {7'b0, abs_dividend, 1'b0};
            cnt <= 0;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin
                wire [16:0] sub_result = {1'b0, shift_reg} - {1'b0, abs_divisor};
                wire carry_out = sub_result[16];
                if (carry_out) begin
                    quotient <= {quotient[6:0], 1'b1};
                    shift_reg <= sub_result[15:0] << 1;
                end else begin
                    quotient <= {quotient[6:0], 1'b0};
                    shift_reg <= shift_reg << 1;
                end
                cnt <= cnt + 1;
            end else begin
                start_cnt <= 0;
                remainder <= shift_reg[15:8];
                res_valid <= 1;
            end
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end
        end
    end
end

always @(posedge clk) begin
    if (rst) begin
        result <= 0;
    end else if (res_valid) begin
        if (sign) begin
            quotient <= (dividend[7] ^ divisor[7]) ? -quotient : quotient;
            remainder <= dividend[7] ? -remainder : remainder;
        end
        result <= {remainder, quotient};
    end
end

endmodule

