module fixed_point_adder #(
    parameter Q = 8,  
    parameter N = 16  
) (
    input [N-1:0] a,  
    input [N-1:0] b,  
    output [N-1:0] c  
);


    reg [N-1:0] res;

    always @(*) begin

        if (a[N-1] == b[N-1]) begin
            res = a + b;

        end else begin

            if (a >= 0) begin
                if (b >= 0) begin

                    res = a + b;
                end else begin

                    if (a > -b) res = a - (-b);
                    else res = -b - a;
                end
            end else begin
                if (b >= 0) begin

                    if (-a > b) res = -a - b;
                    else res = b - (-a);
                end else begin

                    res = a + b;
                end
            end
        end
    end

    assign c = res;

endmodule

