module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [7:0] exponent;
    reg [22:0] mantissa;
    reg [22:0] rounded_mantissa;
    reg overflow, underflow;


    wire a_zero = (a_exponent == 8'd0) && (a_mantissa == 23'd0);
    wire b_zero = (b_exponent == 8'd0) && (b_mantissa == 23'd0);
    wire a_inf = (a_exponent == 8'hff) && (a_mantissa == 23'd0);
    wire b_inf = (b_exponent == 8'hff) && (b_mantissa == 23'd0);
    wire a_nan = (a_exponent == 8'hff) && (a_mantissa != 23'd0);
    wire b_nan = (b_exponent == 8'hff) && (b_mantissa != 23'd0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
        end else begin
            case (counter)

                3'd0: begin
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];


                    a_mantissa_full <= (a_exponent == 8'd0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_full <= (b_exponent == 8'd0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};


                    if (a_nan || b_nan) begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end else if (a_inf && b_inf) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (a_inf || b_inf) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (a_zero || b_zero) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                    end else begin
                        product <= a_mantissa_full * b_mantissa_full;
                        counter <= 3'd1;
                    end
                end


                3'd1: begin

                    integer i;
                    reg [47:0] shifted_product;
                    reg [22:0] truncated_mantissa;
                    reg [8:0] exp;

                    shifted_product = product;
                    exp = 8'd0;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (shifted_product[i]) begin

                            integer shift = 47 - i;
                            shifted_product = product << shift;
                            exp = a_exponent + b_exponent - 8'd127 + shift;
                            truncated_mantissa = shifted_product[46:24];
                            guard_bit = shifted_product[23];
                            round_bit = shifted_product[22];
                            sticky = |shifted_product[21:0];
                            break;
                        end
                    end


                    if (guard_bit && (round_bit || sticky)) begin
                        rounded_mantissa = truncated_mantissa + 1;
                    end else if (guard_bit && !(round_bit || sticky) && truncated_mantissa[0]) begin
                        rounded_mantissa = truncated_mantissa + 1;
                    end else begin
                        rounded_mantissa = truncated_mantissa;
                    end


                    if (rounded_mantissa[23]) begin
                        rounded_mantissa = rounded_mantissa >> 1;
                        exp = exp + 1;
                    end


                    overflow = (exp > 8'hfe);
                    underflow = (exp < 8'd1);

                    exponent <= exp;
                    mantissa <= rounded_mantissa[22:0];
                    counter <= 3'd2;
                end


                3'd2: begin
                    if (a_nan || b_nan) begin
                        z <= {1'b0, 8'hff, 23'h1};
                    end else if (a_inf || b_inf) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (overflow) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};
                    end else if (underflow) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent, mantissa};
                    end
                    counter <= 3'd0;
                end

                default: counter <= 3'd0;
            endcase
        end
    end

endmodule

