module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);


    parameter S0 = 3'b000, S1 = 3'b001, S2 = 3'b010, S3 = 3'b011, S4 = 3'b100, S5 = 3'b101;
    reg [2:0] current_state, next_state;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        next_state = current_state;
        MATCH = 0;

        case (current_state)
            S0: 
                if (IN) next_state = S1;
                else next_state = S0;
            S1: 
                if (!IN) next_state = S2;
                else next_state = S1;
            S2: 
                if (!IN) next_state = S3;
                else next_state = S1;
            S3: 
                if (IN) next_state = S4;
                else next_state = S0;
            S4: 
                if (IN) begin
                    next_state = S5;
                    MATCH = 1;
                end else next_state = S0;
            S5: 
                if (IN) next_state = S1;
                else next_state = S0;
            default: next_state = S0;
        endcase
    end

endmodule

