        if (Rst) begin

            SP <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
            dataOut <= 0;
        end else begin
            if (!FULL) begin 
                if (RW == 0) begin 
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                end else begin 
                    dataOut <= stack_mem[SP-1];
                    stack_mem[SP-1] <= 0;

                    SP <= SP - 1;
                end
            end
        end
    end
end

