module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            cnt <= 10;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_green <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && p_green && cnt > 10) 
                        cnt <= 10;
                    else if (cnt == 0) begin
                        state <= s2_yellow;
                        p_green <= 0;
                        p_yellow <= 1;
                        cnt <= 5;
                    end else 
                        cnt <= cnt - 1;
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_yellow <= 0;
                        p_red <= 1;
                        cnt <= 10;
                    end else 
                        cnt <= cnt - 1;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state == idle)
                cnt <= 10;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b000;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

    assign clock = cnt;

endmodule

