module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam SETUP = 2'b01;
    localparam PROCESS = 2'b10;

    reg [7:0] abs_dividend, abs_divisor, neg_divisor;
    reg sign_dividend, sign_divisor;
    reg sign_quotient;
    reg [15:0] sr;

    reg [3:0] cnt;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            sr <= 16'b0;
            cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        if (sign) begin
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                        end else begin
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                        end
                        neg_divisor <= -abs_divisor;
                        sr <= {8'b0, abs_dividend};
                        cnt <= 0;
                        state <= PROCESS;
                        res_valid <= 0;
                    end
                end

                PROCESS: begin
                    if (cnt < 8) begin

                        if (sr[15]) begin
                            sr[15:8] <= sr[15:8] + neg_divisor;
                        end else begin
                            sr[15:8] <= sr[15:8] - abs_divisor;
                        end


                        sr <= {sr[14:0], 1'b0};

                        sr[0] <= ~sr[15];


                        cnt <= cnt + 1;
                    end else begin

                        state <= IDLE;
                        res_valid <= 1;


                        if (sign) begin
                            if (sign_dividend) begin
                                result[15:8] <= -sr[15:8];
                            end else begin
                                result[15:8] <= sr[15:8];
                            end

                            if (sign_divisor ^ sign_dividend) begin
                                result[7:0] <= -{sr[7:1], 1'b0};
                            end else begin
                                result[7:0] <= {sr[7:1], 1'b0};
                            end
                        end else begin
                            result <= sr;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

