module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] quo;
reg [15:0] rem;

integer i;

always @(*) begin
    rem = 0;
    quo = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        if (i >= 8) begin
            if (A[i -: 8] >= B) begin
                rem = A[i -: 8] - B;
                quo[i] = 1;
            end else begin
                rem = A[i -: 8];
                quo[i] = 0;
            end
        end else begin
            rem = (rem << 1) | A[i];
            if (rem >= B) begin
                rem = rem - B;
                quo[i] = 1;
            end else begin
                quo[i] = 0;
            end
        end
    end

    odd = rem;
end

assign result = quo;

endmodule

