module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire msb_a = a[N-1];
    wire msb_b = b[N-1];

    always @(*) begin
        if (msb_a == msb_b) begin

            res = a + b;
        end else begin

            reg [N-1:0] abs_a, abs_b;
            abs_a = msb_a ? (~a + 1) : a;
            abs_b = msb_b ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                res = a - b;
            end else if (abs_b > abs_a) begin
                res = b - a;
            end else begin

                res = {N{1'b0}};
            end
        end
        c = res;
    end

endmodule

