    output reg rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


reg [PTR_WIDTH-1:0] waddr_bin = 0;
reg [PTR_WIDTH-1:0] wptr_gray = 0;
reg [PTR_WIDTH-1:0] rptr_sync [1:0];


reg [PTR_WIDTH-1:0] raddr_bin = 0;
reg [PTR_WIDTH-1:0] rptr_gray = 0;
reg [PTR_WIDTH-1:0] wptr_sync [1:0];


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
        wptr_gray <= bin2gray(waddr_bin + 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr_gray <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
        rptr_gray <= bin2gray(raddr_bin + 1);
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_sync[0] <= 0;
        rptr_sync[1] <= 0;
    end else begin
        rptr_sync[0] <= rptr_gray;
        rptr_sync[1] <= rptr_sync[0];
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_sync[0] <= 0;
        wptr_sync[1] <= 0;
    end else begin
        wptr_sync[0] <= wptr_gray;
        wptr_sync[1] <= wptr_sync[0];
    end
end


wire full;
wire empty;

assign full = (wptr_gray[PTR_WIDTH-1] != rptr_sync[1][PTR_WIDTH-1]) &&
              (wptr_gray[PTR_WIDTH-2] == rptr_sync[1][PTR_WIDTH-2]) &&
              (wptr_gray[PTR_WIDTH-3:0] == rptr_sync[1][PTR_WIDTH-3:0]);

assign empty = (rptr_gray == wptr_sync[1]);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wfull <= 0;
    end else begin
        wfull <= full;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rempty <= 1;
    end else begin
        rempty <= empty;
    end
end


function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = (bin >> 1) ^ bin;
endfunction

