module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 4;
            EMPTY <= 1;
            FULL <= 0;
            dataOut <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end
        else if (EN) begin
            if (!FULL) begin
                if (!EMPTY) begin
                    if (RW) begin 
                        dataOut <= stack_mem[SP - 1];
                        SP <= SP - 1;
                        if (SP - 1 == 0)
                            EMPTY <= 1;
                        FULL <= 0;
                    end
                    else begin 
                        stack_mem[SP] <= dataIn;
                        SP <= SP + 1;
                        if (SP + 1 == 4)
                            FULL <= 1;
                        EMPTY <= 0;
                    end
                end
                else begin 
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                    if (SP + 1 == 4)
                        FULL <= 1;
                    EMPTY <= 0;
                end
            end
        end
    end

    always @(*) begin
        EMPTY = (SP == 0);
        FULL = (SP == 4);
    end

endmodule

