module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter [1:0] IDLE = 2'b00,
                     GREEN = 2'b01,
                     YELLOW = 2'b10,
                     RED = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg pass_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pass_reg <= 0;
        else
            pass_reg <= pass_request;
    end

    wire pass_rise = pass_request & ~pass_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            IDLE:    next_state = GREEN;
            GREEN:   next_state = (cnt == 0) ? YELLOW : GREEN;
            YELLOW:  next_state = (cnt == 0) ? RED : YELLOW;
            RED:     next_state = (cnt == 0) ? GREEN : RED;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd60;
        else begin
            case (state)
                GREEN: begin
                    if (pass_rise && cnt > 10)
                        cnt <= 8'd10;
                    else if (cnt == 0)
                        cnt <= 8'd5;
                    else
                        cnt <= cnt - 1;
                end
                YELLOW: begin
                    if (cnt == 0)
                        cnt <= 8'd10;
                    else
                        cnt <= cnt - 1;
                end
                RED: begin
                    if (cnt == 0)
                        cnt <= 8'd60;
                    else
                        cnt <= cnt - 1;
                end
                default: cnt <= 0;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            clock <= 0;
        end else begin
            clock <= cnt;
            case (state)
                GREEN: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 1;
                end
                YELLOW: begin
                    red <= 0;
                    yellow <= 1;
                    green <= 0;
                end
                RED: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
            endcase
        end
    end

endmodule

