    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 1'b0;
            wave  <= 5'b0;
        end else begin
            case (state)
                1'b0: begin
                    if (wave == 5'b11111) begin 
                        state <= 1'b1;
                        wave  <= wave;

