module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg sign_reg;
    reg [7:0] neg_divisor;
    reg [16:0] sr;

    reg [3:0] cnt;
    reg start_cnt;
    reg dividend_sign, divisor_sign;
    wire [7:0] abs_dividend;
    wire [7:0] abs_divisor;


    assign abs_dividend = sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
    assign abs_divisor = sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            sr <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_reg <= 0;
            neg_divisor <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_reg <= sign;
                dividend_sign <= dividend[7];
                divisor_sign <= divisor[7];
                dividend_reg <= abs_dividend;
                divisor_reg <= abs_divisor;

                sr <= {abs_dividend, 1'b0};

                neg_divisor <= -abs_divisor;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin

                    {sr[16:8], sr[7:0], 1'b0} = sr[16:8] - neg_divisor;

                    sr <= {sr[16:9] - (sr[16:9] < neg_divisor ? 0 : neg_divisor), 
                           {sr[7:0], 1'b0}};
                    cnt <= cnt + 1;
                end else begin

                    start_cnt <= 0;

                    if (sign_reg) begin

                        if (dividend_sign ^ divisor_sign) begin
                            result[7:0] <= ~sr[7:0] + 1;
                        end else begin
                            result[7:0] <= sr[7:0];
                        end

                        if (dividend_sign) begin
                            result[15:8] <= ~sr[16:9] + 1;
                        end else begin
                            result[15:8] <= sr[16:9];
                        end
                    end else begin
                        result <= {sr[16:9], sr[7:0]};
                    end
                    res_valid <= 1;
                end
            end
        end
    end


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
        end else if (start_cnt && cnt == 9) begin
            res_valid <= 0;
        end
    end

endmodule

