    if (a[N-1] == b[N-1]) begin

        res = {a[N-1], (a[N-2:0] + b[N-2:0])};
    end else begin

        if (a[N-2:0] > b[N-2:0]) begin
            res = {a[N-1], a[N-2:0] - b[N-2:0]};
        end else if (b[N-2:0] > a[N-2:0]) begin
            res = {b[N-1], b[N-2:0] - a[N-2:0]};
        end else begin

            res = {1'b0, {N-1{1'b0}}};
        end
    end
end

assign c = res;

endmodule

