module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [23:0] a_mantissa_24, b_mantissa_24;
    reg guard_bit, round_bit, sticky;
    reg [22:0] rounded_mantissa;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'h0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 8'h0;
            b_exponent <= 8'h0;
            a_mantissa <= 23'h0;
            b_mantissa <= 23'h0;
        end else begin
            case (counter)
                3'b0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 3'b1;
                end

                3'b1: begin

                    a_mantissa_24 <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_24 <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    product <= a_mantissa_24 * b_mantissa_24;
                    z_exponent <= (a_exponent == 0 ? 126 : a_exponent - 127) + (b_exponent == 0 ? 126 : b_exponent - 127);
                    counter <= 3'b2;
                end

                3'b2: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 3'b3;
                end

                3'b3: begin

                    {guard_bit, round_bit, sticky} = {product[1:0], |product[0:22]};
                    if (guard_bit && (round_bit || sticky)) begin
                        rounded_mantissa = product[46:24] + 1;
                        if (rounded_mantissa[23]) begin
                            product <= product << 1;
                            z_exponent <= z_exponent + 1;
                        end
                    end else begin
                        rounded_mantissa = product[46:24];
                    end


                    overflow = (z_exponent > 254);
                    underflow = (z_exponent[7:0] < 1);
                    if (a == 32'h00000000 || b == 32'h00000000) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else if (overflow) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (underflow) begin
                        z <= {a_sign ^ b_sign, 8'h0, rounded_mantissa[22:0]};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= 3'b0;
                end
            endcase
        end
    end

endmodule

