module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_BITS = ADDR_BITS + 1;


reg [PTR_BITS-1:0] wptr_bin, rptr_bin;


wire [PTR_BITS-1:0] wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
wire [PTR_BITS-1:0] rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


reg [PTR_BITS-1:0] wptr_gray_sync_rd0, wptr_gray_sync_rd1;
reg [PTR_BITS-1:0] rptr_gray_sync_wr0, rptr_gray_sync_wr1;


wire [PTR_BITS-1:0] wptr_bin_sync_rd = gray2bin(wptr_gray_sync_rd1);
wire [PTR_BITS-1:0] rptr_bin_sync_wr = gray2bin(rptr_gray_sync_wr1);


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc & ~wfull),
    .waddr(wptr_bin[ADDR_BITS-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc & ~rempty),
    .raddr(rptr_bin[ADDR_BITS-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wptr_bin <= 0;
    else if (winc & ~wfull) wptr_bin <= wptr_bin + 1;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rptr_bin <= 0;
    else if (rinc & ~rempty) rptr_bin <= rptr_bin + 1;
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) {wptr_gray_sync_rd1, wptr_gray_sync_rd0} <= 0;
    else begin
        wptr_gray_sync_rd0 <= wptr_gray;
        wptr_gray_sync_rd1 <= wptr_gray_sync_rd0;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) {rptr_gray_sync_wr1, rptr_gray_sync_wr0} <= 0;
    else begin
        rptr_gray_sync_wr0 <= rptr_gray;
        rptr_gray_sync_wr1 <= rptr_gray_sync_wr0;
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull <= 0;
    else wfull <= (wptr_bin - rptr_bin_sync_wr) >= DEPTH;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty <= 1;
    else rempty <= (rptr_bin == wptr_bin_sync_rd);
end


function [PTR_BITS-1:0] gray2bin;
    input [PTR_BITS-1:0] gray;
    reg [PTR_BITS-1:0] bin;
    integer i;
    begin
        bin[PTR_BITS-1] = gray[PTR_BITS-1];
        for (i = PTR_BITS-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

endmodule

