module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter [1:0] idle = 2'b00;
    parameter [1:0] s1_red = 2'b01;
    parameter [1:0] s2_yellow = 2'b10;
    parameter [1:0] s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
            cnt <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                    cnt <= 8'd9;

                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        red <= 0;
                        green <= 1;
                        cnt <= 8'd59;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && green && (cnt > 10)) begin
                        cnt <= cnt - 8'd10 - 1;

                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        green <= 0;
                        yellow <= 1;
                        cnt <= 8'd4;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        yellow <= 0;
                        red <= 1;
                        cnt <= 8'd9;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(*) begin
        case (state)
            s1_red: {red, yellow, green} = 3'b100;
            s3_green: {red, yellow, green} = 3'b001;
            s2_yellow: {red, yellow, green} = 3'b010;
            default: {red, yellow, green} = 3'b000;
        endcase
    end

    assign clock = cnt;

endmodule

