module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    assign flag = (aluc == SLT) ? ($signed(a) < $signed(b)) :
                  (aluc == SLTU) ? (a < b) : 1'bz;


    assign zero = (r == 32'b0);
    assign negative = r[31];

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry, r} = {a[31], a} + {b[31], b};
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                {carry, r} = a + b;
                overflow = 0;
            end
            SUB: begin
                {carry, r} = {a[31], a} - {b[31], b};
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
                carry = (a < b);
            end
            SUBU: begin
                r = a - b;
                carry = (a < b);
                overflow = 0;
            end
            AND: begin
                r = a & b;
                carry = 0;
                overflow = 0;
            end
            OR: begin
                r = a | b;
                carry = 0;
                overflow = 0;
            end
            XOR: begin
                r = a ^ b;
                carry = 0;
                overflow = 0;
            end
            NOR: begin
                r = ~ (a | b);
                carry = 0;
                overflow = 0;
            end
            SLT: begin
                r = {31'b0, ($signed(a) < $signed(b))};
                carry = 0;
                overflow = 0;
            end
            SLTU: begin
                r = {31'b0, (a < b)};
                carry = 0;
                overflow = 0;
            end
            SLL: begin
                r = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRL: begin
                r = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRA: begin
