module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg quotient_sign;
reg remainder_sign;
reg [15:0] SR;

reg [3:0] cnt;
reg busy;

always @(posedge clk) begin
    if (rst) begin
        busy <= 0;
        res_valid <= 0;
        result <= 0;
        SR <= 0;
        cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
    end else begin
        if (opn_valid && !busy && !res_valid) begin
            busy <= 1;
            res_valid <= 0;

            if (sign) begin
                dividend_abs <= dividend[7] ? (~dividend + 1) : dividend;
                divisor_abs <= divisor[7] ? (~divisor + 1) : divisor;
                quotient_sign <= dividend[7] ^ divisor[7];
                remainder_sign <= dividend[7];
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
                quotient_sign <= 0;
                remainder_sign <= 0;
            end

            SR <= {dividend_abs, 8'b0} << 1;
            cnt <= 1;
        end else if (busy) begin
            if (cnt <= 8) begin
                if (cnt == 8) begin

                    result <= {SR[15:8], SR[7:0]};

                    if (sign) begin
                        if (remainder_sign)
                            result[15:8] <= -result[15:8];
                        if (quotient_sign)
                            result[7:0] <= -result[7:0];
                    end
                    res_valid <= 1;
                    busy <= 0;
                    cnt <= 0;
                end else begin

                    if (SR[15:8] >= divisor_abs) begin
                        SR <= {SR[15:8] - divisor_abs, SR[7:0], 1'b1} << 1;
                    end else begin
                        SR <= {SR[15:8], SR[7:0], 1'b0} << 1;
                    end
                    cnt <= cnt + 1;
                end
            end
        end

        if (opn_valid && !busy && !res_valid)
            res_valid <= 0;
    end
end

endmodule

