            areg <= ain;
            breg <= bin;
            yout_r <= 0;
        end


        if (i > 0 && i < 17) begin
            if (areg[i-1])
                yout_r <= yout_r + (breg << (i-1));
        end


        case (i)
            16: done_r <= 1;
            17: done_r <= 0;
            default: done_r <= done_r;
        endcase


        yout <= yout_r;
        done <= done_r;
    end
end

