module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [7:0] buffer [3:0];
reg [1:0] count;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        valid_out <= 0;
        data_out <= 0;
        for (i = 0;
 i < 4;
 i = i + 1)
            buffer[i] <= 0;
    end else begin
        valid_out <= 0;
        if (valid_in) begin
            buffer[count] <= data_in;
            if (count == 3) begin
                valid_out <= 1;
                data_out <= buffer[0] + buffer[1] + buffer[2] + buffer[3];
                count <= 0;
            end else
                count <= count + 1;
        end
    end
end

endmodule

