module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg [N-1:0] a_signed = a;
        reg [N-1:0] b_signed = b;
        reg sign_a = a[N-1];
        reg sign_b = b[N-1];

        if (sign_a == sign_b) begin

            res = a_signed + b_signed;
        end else begin

            if (a_signed > b_signed) begin
                res = a_signed - b_signed;
            end else if (b_signed > a_signed) begin
                res = b_signed - a_signed;
            end else begin

                res = {N{1'b0}};
            end
        end
    end

    assign c = res;

endmodule

