module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt >= 10) ? s3_green : s1_red;
            s3_green: next_state = (cnt >= 5) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt >= 5) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && (state == s3_green)) begin
                if (cnt > 10) cnt <= 10;
                else cnt <= cnt;
            end else if (state == s1_red && next_state != state) begin
                cnt <= 60;
            end else if (state == s3_green && next_state != state) begin
                cnt <= 5;
            end else if (state == s2_yellow && next_state != state) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            p_red <= (state == s1_red);
            p_yellow <= (state == s2_yellow);
            p_green <= (state == s3_green);
        end
    end

    assign clock = cnt;
    assign {red, yellow, green} = {p_red, p_yellow, p_green};

endmodule

