    reg data_available;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_lock <= 8'b0;
            data_available <= 1'b0;
            data_out <= 16'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                if (!data_available) begin
                    data_lock <= data_in;
                    data_available <= 1'b1;
                end else begin
                    data_out <= {data_lock, data_in};
                    valid_out <= 1'b1;
                    data_available <= 1'b0;
                end
            end
        end
    end

