module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg state;
    localparam IDLE = 0;
    localparam BUSY = 1;

    reg [7:0] abs_dividend, abs_divisor;
    reg sign_quotient, sign_remainder;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            SR <= 0;
            cnt <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                            sign_quotient <= dividend[7] ^ divisor[7];
                            sign_remainder <= dividend[7];
                        end else begin
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                            sign_quotient <= 0;
                            sign_remainder <= 0;
                        end


                        SR <= {abs_dividend, 8'b0} << 1;
                        NEG_DIVISOR <= -abs_divisor;

                        cnt <= 0;
                        state <= BUSY;
                        res_valid <= 0;
                    end
                end

                BUSY: begin
                    if (cnt < 8) begin

                        wire [8:0] temp_remainder = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                        if (!temp_remainder[8]) begin
                            SR <= {temp_remainder[7:0], (SR[7:0] << 1) | 1'b1};
                        end else begin
                            SR <= {SR[15:8], (SR[7:0] << 1)};
                        end
                        cnt <= cnt + 1;
                    end else begin

                        state <= IDLE;
                        res_valid <= 1;

                        result <= { (sign ? (sign_remainder ? -SR[15:8] : SR[15:8]) : SR[15:8]),
                                   (sign ? (sign_quotient ? -SR[7:0] : SR[7:0]) : SR[7:0]) };
                    end
                end
            endcase
        end
    end
endmodule

