module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire borrow_0, borrow_1, borrow_2, borrow_3;
    wire [3:0] diff;


    assign borrow_0 = (A[0] < B[0]);
    assign diff[0] = A[0] ^ B[0];


    assign borrow_1 = (A[1] < (B[1] + borrow_0));
    assign diff[1] = A[1] ^ B[1] ^ borrow_0;


    assign borrow_2 = (A[2] < (B[2] + borrow_1));
    assign diff[2] = A[2] ^ B[2] ^ borrow_1;


    assign borrow_3 = (A[3] < (B[3] + borrow_2));
    assign diff[3] = A[3] ^ B[3] ^ borrow_2;


    assign A_less = borrow_3;

    wire diff_all_zero = (diff == 4'b0000);
    assign A_equal = ~borrow_3 & diff_all_zero;
    assign A_greater = ~borrow_3 & ~diff_all_zero;

endmodule

