        if (!rst_n) begin
            i <= 5'b0;
        end else begin
            if (start) begin
                if (i < 17) begin
                    i <= i + 1;
                end else begin
                    i <= 5'b0;
                end
            end else begin
                i <= 5'b0;
            end
        end
    end

