        if (!rst_n) begin
            done <= 0;
        end else begin
            if (i == 16) begin
                done <= 1;
            end else if (i == 17) begin
                done <= 0;
            end else begin
                done <= done;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
