module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N:0] sum_ext;


always @(*) begin
    if (a[N-1] == b[N-1]) begin

        reg [N:0] mag_a, mag_b;
        mag_a = a[N-1] ? (-{1'b0, a}) : {1'b0, a};
        mag_b = b[N-1] ? (-{1'b0, b}) : {1'b0, b};
        sum_ext = mag_a + mag_b;


        if (a[N-1] == 0) begin

            if (sum_ext > (2**(N-1)-1))
                c = {1'b0, {(N-1){1'b1}}};

            else
                c = sum_ext[N-1:0];
        end else begin

            if (sum_ext < -(2**(N-1)))
                c = {1'b1, {(N-1){1'b0}}};

            else
                c = sum_ext[N-1:0];
        end
    end else begin

        reg [N:0] mag_a, mag_b;
        reg [N:0] diff_ext;
        mag_a = a[N-1] ? (-{1'b0, a}) : {1'b0, a};
        mag_b = b[N-1] ? (-{1'b0, b}) : {1'b0, b};

        if (mag_a >= mag_b) begin
            diff_ext = mag_a - mag_b;
            c = {a[N-1], diff_ext[N-2:0]};

        end else begin
            diff_ext = mag_b - mag_a;
            c = {b[N-1], diff_ext[N-2:0]};

        end
    end
end

endmodule

