module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

reg [2:0] counter = 0;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [49:0] product;
reg guard, round, sticky;
reg [7:0] exp_sum;
reg [23:0] mantissa;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};
                counter <= 1;
            end

            1: begin

                if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                    if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin

                        if (a_mantissa == 0 && b_mantissa == 0) begin
                            z <= a_exponent[7] ? {1'b0, 8'hFF, a_mantissa} : {1'b1, 8'hFF, b_mantissa};
                        end else begin
                            z <= {1'b0, 8'hFF, 23'h1};

                        end
                    end else begin
                        if (a_exponent == 8'hFF && a_mantissa == 0) begin
                            if (b_exponent == 8'h00 || b_mantissa == 0) begin
                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                            end else begin
                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                            end
                        end else if (b_exponent == 8'hFF && b_mantissa == 0) begin
                            if (a_exponent == 8'h00 || a_mantissa == 0) begin
                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                            end else begin
                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                            end
                        end
                    end
                    counter <= 7;
                end else if (a_exponent == 8'h00 || a_mantissa == 0) begin

                    if (b_exponent == 8'hFF || b_mantissa == 0) begin
                        z <= {b_sign ^ a_sign, 8'hFF, 23'h0};

                    end else begin
                        z <= {b_sign ^ a_sign, 8'h00, 23'h0};

                    end
                    counter <= 7;
                end else if (b_exponent == 8'h00 || b_mantissa == 0) begin

                    if (a_exponent == 8'hFF || a_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};

                    end
                    counter <= 7;
                end else begin

                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    counter <= 2;
                end
            end

            2: begin

                if (product[47]) begin

                    exp_sum <= a_exponent + b_exponent + 8'd1 - 8'd127;
                    mantissa <= product[46:24];
                    {guard, round, sticky} = {product[23], product[22], |product[21:0]};
                end else begin
                    exp_sum <= a_exponent + b_exponent - 8'd127;
                    mantissa <= product[45:23];
                    {guard, round, sticky} = {product[23], product[22], |product[21:0]};
                end
                counter <= 3;
            end

            3: begin

                if (sticky || (round && mantissa[0])) begin
                    if (mantissa[22:0] == 23'h000000) begin

                        mantissa <= 23'h1;
                        exp_sum <= exp_sum + 1;
                    end else begin
                        mantissa <= mantissa + 1;
                    end
                end
                counter <= 4;
            end

            4: begin

                if (exp_sum > 8'hFF) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                end else if (exp_sum < 8'h00) begin
                    z <= {a_sign ^ b_sign, 8'h00, 23'h0};

                end else begin
                    z <= {a_sign ^ b_sign, exp_sum, mantissa};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

