module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam PULSE1 = 2'b01;
    localparam PULSE2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in)
                        state <= IDLE;
                    else
                        state <= PULSE1;
                end
                PULSE1: begin
                    if (data_in)
                        state <= PULSE2;
                    else
                        state <= IDLE;
                end
                PULSE2: begin
                    if (data_in)
                        state <= IDLE;
                    else
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign data_out = (state == PULSE2) && (data_in == 0);

endmodule

