module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter GREEN = 0;
parameter YELLOW = 1;
parameter RED = 2;

reg [1:0] state;
reg [7:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= GREEN;
        counter <= 8'd60;
        clock <= 8'd60;
    end else begin
        case (state)
            GREEN: begin

                if (pass_request && (60 - counter) > 10) begin
                    counter <= 8'd50;
                end else begin
                    counter <= counter - 1;
                end


                clock <= counter;


                if (counter == 0) begin
                    state <= YELLOW;
                    counter <= 8'd5;
                    clock <= 5;
                end else begin
                    clock <= counter - 1;
                end
            end

            YELLOW: begin
                counter <= counter - 1;
                clock <= counter;

                if (counter == 0) begin
                    state <= RED;
                    counter <= 8'd10;
                    clock <= 10;
                end else begin
                    clock <= counter - 1;
                end
            end

            RED: begin
                counter <= counter - 1;
                clock <= counter;

                if (counter == 0) begin
                    state <= GREEN;
                    counter <= 8'd60;
                    clock <= 60;
                end else begin
                    clock <= counter - 1;
                end
            end

            default: begin
                state <= GREEN;
                counter <= 8'd60;
                clock <= 60;
            end
        endcase
    end
end


always @(*) begin
    case (state)
        GREEN: begin
            red = 0;
            yellow = 0;
            green = 1;
        end
        YELLOW: begin
            red = 0;
            yellow = 1;
            green = 0;
        end
        RED: begin
            red = 1;
            yellow = 0;
            green = 0;
        end
        default: begin
            red = 0;
            yellow = 0;
            green = 0;
        end
    endcase
end

endmodule

