module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] divisor_abs;
    reg dividend_sign;
    reg divisor_sign;
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            divisor_abs <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin
                        res_valid <= 0;
                        if (sign) begin
                            dividend_sign <= dividend[7];
                            divisor_sign <= divisor[7];
                            divisor_abs <= divisor[7] ? -divisor : divisor;
                            SR <= {8'b0, (dividend[7] ? -dividend : dividend)};
                        end else begin
                            divisor_abs <= divisor;
                            SR <= {8'b0, dividend};
                        end
                        cnt <= 0;
                        state <= BUSY;
                    end
                end
                BUSY: begin
                    if (cnt < 8) begin
                        SR <= SR << 1;
                        if (SR[15:8] >= divisor_abs) begin
                            SR[15:8] <= SR[15:8] - divisor_abs;
                            SR[0] <= 1'b1;
                        end else begin
                            SR[0] <= 1'b0;
                        end
                        cnt <= cnt + 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    state <= IDLE;
                    if (sign) begin
                        reg [7:0] quotient = SR[7:0];
                        reg [7:0] remainder = SR[15:8];
                        if (dividend_sign ^ divisor_sign) begin
                            quotient = -quotient;
                        end
                        if (dividend_sign) begin
                            remainder = -remainder;
                        end
                        result <= {remainder, quotient};
                    end else begin
                        result <= SR;
                    end
                    res_valid <= 1;
                end
            endcase
        end
    end

endmodule

