module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [8:0] rem;
integer i;

always @(*) begin
    rem = 9'b0;
    result = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = {rem[7:0], A[i]};
        if (rem >= {1'b0, B}) begin
            rem = rem - {1'b0, B};
            result[i] = 1'b1;
        end else begin
            result[i] = 1'b0;
        end
    end

    odd = {8'b0, rem[7:0]};
end

endmodule

