module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input cin,
    output [16:1] S,
    output cout
);
    wire [16:0] C;
    assign C[0] = cin;


    wire [16:1] G, P;
    genvar i;
    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gp
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] ^ B[i];
        end
    endgenerate


    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : carry
            wire [i:1] terms;
            for (integer j = 1;
 j <= i;
 j = j + 1) begin : term
                if (j == i) begin
                    assign terms[j] = G[j];
                end else begin
                    wire [i:1] p_slice = P[j+1:i];
                    assign terms[j] = (&p_slice) & G[j];
                end
            end
            assign C[i] = |terms;
        end
    endgenerate


    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : sum
            assign S[i] = P[i] ^ C[i-1];
        end
    endgenerate

    assign cout = C[16];
