module fixed_point_adder #(parameter Q = 4, N = 8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    reg a_sign, b_sign;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] sum;
    reg [N-1:0] diff;
    reg c_sign;

    a_sign = a[N-1];
    b_sign = b[N-1];

    a_abs = a_sign ? (-a) : a;
    b_abs = b_sign ? (-b) : b;

    if (a_sign == b_sign) begin
        sum = a_abs + b_abs;
        c_sign = a_sign;
    end else begin
        if (a_abs > b_abs) begin
            diff = a_abs - b_abs;
            c_sign = a_sign;
        end else if (b_abs > a_abs) begin
            diff = b_abs - a_abs;
            c_sign = b_sign;
        end else begin
            diff = 0;
            c_sign = 0;
        end
        sum = diff;
    end

    if (c_sign)
        res = -sum;
    else
        res = sum;

    c = res;
end

endmodule

