module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [31:0] a_reg, b_reg;
reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [49:0] product;
reg [47:0] normalized_product;
reg [7:0] leading_zeros;
reg [23:0] rounded_mantissa;
reg [9:0] final_exponent;

function [7:0] leading_zero_count;
    input [47:0] val;
    integer i;
    begin
        leading_zero_count = 8'h0;
        for (i = 47;
 i >= 0;
 i = i - 1) begin
            if (val[i] == 1'b1) begin
                leading_zero_count = 8'h47 - i;
                break;
            end
        end
    end
endfunction

function [23:0] round_mantissa;
    input [47:0] product;
    input [7:0] leading_zeros;
    reg guard_bit, round_bit, sticky_bit;
    begin
        guard_bit = product[23 - leading_zeros];
        round_bit = product[22 - leading_zeros];
        sticky_bit = |product[21 - leading_zeros : 0];
        if (guard_bit && (round_bit || sticky_bit)) begin
            rounded_mantissa = {product[47 - leading_zeros : 24 - leading_zeros], 3'b1} + 1;
        end else begin
            rounded_mantissa = {product[47 - leading_zeros : 24 - leading_zeros], 3'b0};
        end
        if (rounded_mantissa[23]) begin
            rounded_mantissa = rounded_mantissa + 1;
        end
        round_mantissa = rounded_mantissa;
    end
endfunction

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b000;
        z <= 32'b0;
        a_reg <= 32'b0;
        b_reg <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin
                a_reg <= a;
                b_reg <= b;
                counter <= counter + 1;
            end
            3'b001: begin
                a_sign <= a_reg[31];
                b_sign <= b_reg[31];
                a_exponent <= a_reg[30:23];
                b_exponent <= b_reg[30:23];
                a_mantissa <= (a_reg[30:23] == 0) ? {1'b0, a_reg[22:0]} : {1'b1, a_reg[22:0]};
                b_mantissa <= (b_reg[30:23] == 0) ? {1'b0, b_reg[22:0]} : {1'b1, b_reg[22:0]};
                counter <= counter + 1;
            end
            3'b010: begin
                product <= {24'b0, a_mantissa} * {24'b0, b_mantissa};
                counter <= counter + 1;
            end
            3'b011: begin
                leading_zeros <= leading_zero_count(product[47:0]);
                normalized_product <= product << leading_zeros;
                final_exponent <= a_exponent + b_exponent - 9'd127 + leading_zeros;
                counter <= counter + 1;
            end
            3'b100: begin
                rounded_mantissa <= round_mantissa(normalized_product, leading_zeros);
                counter <= counter + 1;
            end
            3'b101: begin
                if (final_exponent >= 9'd255) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                end else if (final_exponent == 0) begin
                    z <= {a_sign ^ b_sign, 31'b0};
                end else begin
                    z <= {a_sign ^ b_sign, final_exponent[7:0], rounded_mantissa[22:0]};
                end
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

