    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc & ~rempty),
    .raddr(rptr_bin),
    .rdata(rdata)
);


always @(posedge wclk) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
        wptr_gray <= bin2gray(wptr_bin + 1);
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


always @(posedge rclk) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
        rptr_gray <= bin2gray(rptr_bin + 1);
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


wire [PTR_WIDTH-1:0] rptr_bin_synced = gray2bin(rptr_gray_sync2);
wire [PTR_WIDTH-1:0] wptr_bin_synced = gray2bin(wptr_gray_sync2);


assign wfull = (wptr_bin + 1 == rptr_bin_synced);
assign rempty = (wptr_bin_synced == rptr_bin);


function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] bin;
    integer i;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

