module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


parameter ADD    = 6'b100000;
parameter ADDU   = 6'b100001;
parameter SUB    = 6'b100010;
parameter SUBU   = 6'b100011;
parameter AND    = 6'b100100;
parameter OR     = 6'b100101;
parameter XOR    = 6'b100110;
parameter NOR    = 6'b100111;
parameter SLT    = 6'b101010;
parameter SLTU   = 6'b101011;
parameter SLL    = 6'b000000;
parameter SRL    = 6'b000010;
parameter SRA    = 6'b000011;
parameter SLLV   = 6'b000100;
parameter SRLV   = 6'b000110;
parameter SRAV   = 6'b000111;
parameter LUI    = 6'b001111;

reg [4:0] shamt;

always @(*) begin
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = a + b;
            overflow = 0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = a - b;
            overflow = 0;
        end
        AND:   r = a & b;
        OR:    r = a | b;
        XOR:   r = a ^ b;
        NOR:   r = ~(a | b);
        SLT:   r = ($signed(a) < $signed(b)) ? 1 : 0;
        SLTU:  r = (a < b) ? 1 : 0;
        SLL: begin
            shamt = a[4:0];
            r = b << shamt;
            carry = (shamt == 0) ? 0 : (b >> (32 - shamt)) & 1;
        end
        SRL: begin
            shamt = a[4:0];
            r = b >> shamt;
            carry = (shamt == 0) ? 0 : (b >> (shamt - 1)) & 1;
        end
        SRA: begin
            shamt = a[4:0];
            r = $signed(b) >>> shamt;
            carry = (shamt == 0) ? 0 : (b >> (shamt - 1)) & 1;
        end
        SLLV: begin
            shamt = a[4:0];
            r = b << shamt;
            carry = (shamt == 0) ? 0 : (b >> (32 - shamt)) & 1;
        end
        SRLV: begin
            shamt = a[4:0];
            r = b >> shamt;
            carry = (shamt == 0) ? 0 : (b >> (shamt - 1)) & 1;
        end
        SRAV: begin
            shamt = a[4:0];
            r = $signed(b) >>> shamt;
            carry = (shamt == 0) ? 0 : (b >> (shamt - 1)) & 1;
        end
        LUI:   r = {b[15:0], 16'b0};
        default: r = 32'bz;
    endcase
end

assign zero = (r == 0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

