module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg [8:0] SR;
reg [3:0] cnt;
reg [7:0] NEG_DIVISOR;
reg [7:0] quotient;
reg remainder;

localparam IDLE = 2'b00;
localparam DIVIDE = 2'b01;

reg [1:0] state;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 0;
        cnt <= 0;
        SR <= 0;
        quotient <= 0;
        remainder <= 0;
        NEG_DIVISOR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        abs_dividend <= dividend[7] ? (-dividend) : dividend;
                        abs_divisor <= divisor[7] ? (-divisor) : divisor;
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                    end

                    SR <= {abs_dividend, 1'b0};
                    NEG_DIVISOR <= -abs_divisor;
                    cnt <= 1;
                    state <= DIVIDE;
                end
            end
            DIVIDE: begin
                if (cnt <= 8) begin

                    if (SR[8:1] >= NEG_DIVISOR) begin
                        remainder <= SR[8:1] - NEG_DIVISOR;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        remainder <= SR[8:1];
                        quotient <= {quotient[6:0], 1'b0};
                    end

                    SR <= {remainder, quotient[0]};
                    cnt <= cnt + 1;
                end else begin
                    state <= IDLE;

                    if (sign) begin

                        quotient <= (abs_dividend[7] ^ abs_divisor[7]) ? -quotient : quotient;
                        remainder <= (abs_dividend[7] && (remainder != 0)) ? (remainder - abs_divisor) : remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end
            end
        endcase
    end
end

endmodule

