module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire [3:0] diff;
wire [3:0] borrow;

full_subtractor fs0 (
    .A(A[0]),
    .B(B[0]),
    .borrow_in(1'b0),
    .diff(diff[0]),
    .borrow_out(borrow[0])
);

full_subtractor fs1 (
    .A(A[1]),
    .B(B[1]),
    .borrow_in(borrow[0]),
    .diff(diff[1]),
    .borrow_out(borrow[1])
);

full_subtractor fs2 (
    .A(A[2]),
    .B(B[2]),
    .borrow_in(borrow[1]),
    .diff(diff[2]),
    .borrow_out(borrow[2])
);

full_subtractor fs3 (
    .A(A[3]),
    .B(B[3]),
    .borrow_in(borrow[2]),
    .diff(diff[3]),
    .borrow_out(borrow[3])
);

assign A_less = borrow[3];
assign A_equal = (diff == 4'b0) && ~borrow[3];
assign A_greater = (diff != 4'b0) && ~borrow[3];

