module full_subtractor (
    input A,
    input B,
    input borrow_in,
    output diff,
    output borrow_out
);

assign diff = A ^ B ^ borrow_in;
assign borrow_out = (~A & B) | ((A ~^ B) & borrow_in);

endmodule

