module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] temp;
    reg sign;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a + b;
        end else begin


            a_abs = a[N-1] ? (~a + 1) : a;
            b_abs = b[N-1] ? (~b + 1) : b;


            if (a_abs > b_abs) begin
                temp = a_abs - b_abs;
                sign = 1'b0;
            end else if (b_abs > a_abs) begin
                temp = b_abs - a_abs;
                sign = 1'b1;
            end else begin
                temp = {N{1'b0}};

                sign = 1'b0;
            end


            if (sign) begin
                res = ~temp + 1;
            end else begin
                res = temp;
            end
        end

        c = res;
    end

endmodule

