module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] full_a_mantissa, full_b_mantissa;
reg [47:0] product;
reg [9:0] exponent_sum;
reg [23:0] normalized_mantissa;
reg [47:0] shifted_product;
reg guard_bit, round_bit, sticky;

localparam UNPACK = 3'b000;
localparam MULTIPLY = 3'b001;
localparam NORMALIZE = 3'b010;
localparam ROUND = 3'b011;
localparam ADJUST = 3'b100;
localparam PACK = 3'b101;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 0;
    end else begin
        case (counter)
            UNPACK: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];

                if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                    z <= 32'h7FC00000;
                    counter <= PACK;
                end else if (a_exponent == 0 && a_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 31'b0};
                    counter <= PACK;
                end else if (b_exponent == 0 && b_mantissa == 0) begin
                    z <= {a_sign ^ b_sign, 31'b0};
                    counter <= PACK;
                end else begin
                    full_a_mantissa <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    full_b_mantissa <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    counter <= MULTIPLY;
                end
            end

            MULTIPLY: begin
                product <= full_a_mantissa * full_b_mantissa;
                counter <= NORMALIZE;
            end

            NORMALIZE: begin
                if (product[47:46] >= 2'b10) begin
                    shifted_product <= product >> 1;
                    exponent_sum <= (a_exponent + b_exponent - 9'h080) + 1;
                    normalized_mantissa <= {1'b1, shifted_product[46:24]};
                end else begin
                    shifted_product <= product;
                    exponent_sum <= a_exponent + b_exponent - 9'h080;
                    normalized_mantissa <= {1'b1, product[47:25]};
                end
                counter <= ROUND;
            end

            ROUND: begin
                guard_bit <= shifted_product[24];
                round_bit <= shifted_product[23];
                sticky <= |shifted_product[22:0];

                if (guard_bit && (round_bit || sticky)) begin
                    if (normalized_mantissa[0]) begin
                        normalized_mantissa <= normalized_mantissa + 1;
                    end
                end else if (guard_bit && !round_bit && !sticky) begin
                    normalized_mantissa <= normalized_mantissa + 1;
                end
                counter <= ADJUST;
            end

            ADJUST: begin
                if (exponent_sum >= 9'h0FF) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                end else if (exponent_sum[9]) begin
                    z <= 32'b0;
                end else begin
                    z <= {a_sign ^ b_sign, exponent_sum[7:0], normalized_mantissa[22:0]};
                end
                counter <= PACK;
            end

            PACK: begin
                counter <= UNPACK;
            end

            default: counter <= UNPACK;
        endcase
    end
end

endmodule

