module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


initial begin
    SP = 3'b100;

    stack_mem[0] = 0;
    stack_mem[1] = 0;
    stack_mem[2] = 0;
    stack_mem[3] = 0;
end

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
    end
    else if (EN) begin
        if (!FULL) begin
            if (!RW) begin 
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end
            else begin 
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 0;
                SP <= SP + 1;
            end
        end
    end
end

assign EMPTY = (SP == 3'b100);

assign FULL = (SP == 3'b000);


