module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red, yellow, green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:    state <= s1_red;
                s1_red:  state <= (cnt == 3) ? s3_green : s1_red;
                s2_yellow: state <= (cnt == 3) ? s1_red : s2_yellow;
                s3_green: state <= (cnt == 3) ? s2_yellow : s3_green;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                if (cnt > 10) cnt <= 10;
            end else if (!green && p_green) begin
                cnt <= 60;
            end else if (!yellow && p_yellow) begin
                cnt <= 5;
            end else if (!red && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            {p_red, p_yellow, p_green} <= {red, yellow, green};
        end
    end


    always @(*) begin
        case (state)
            idle:    {red, yellow, green} = 3'b000;
            s1_red:  {red, yellow, green} = 3'b100;
            s2_yellow: {red, yellow, green} = 3'b010;
            s3_green: {red, yellow, green} = 3'b001;
            default: {red, yellow, green} = 3'b000;
        endcase
    end

    assign clock = cnt;

endmodule

