module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] neg_divisor;
    reg start_cnt;
    reg div_sign, div_neg;


    always @(posedge clk) begin
        if (rst) begin
            SR <= 16'h0;
            cnt <= 4'h0;
            start_cnt <= 1'b0;
            res_valid <= 1'b0;
            abs_dividend <= 8'h0;
            abs_divisor <= 8'h0;
            neg_divisor <= 8'h0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    div_sign <= dividend[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    div_neg <= divisor[7];
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    neg_divisor <= -(divisor[7] ? -divisor : divisor);
                end else begin
                    div_sign <= 1'b0;
                    div_neg <= 1'b0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    neg_divisor <= -divisor;
                end

                SR <= {abs_dividend, 8'b0} << 1;
                cnt <= 4'h1;
                start_cnt <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt == 4'h8) begin

                    start_cnt <= 1'b0;
                    cnt <= 4'h0;
                    res_valid <= 1'b1;

                    if (sign) begin

                        reg [7:0] quo, rem;
                        quo = div_sign ^ div_neg ? -SR[7:0] : SR[7:0];
                        rem = div_sign ? -SR[15:8] : SR[15:8];
                        result <= {rem, quo};
                    end else begin
                        result <= {SR[15:8], SR[7:0]};
                    end
                end else begin

                    reg [9:0] temp;
                    temp = {1'b0, SR[15:8]} + {1'b0, abs_divisor};
                    if (temp[9] == 0) begin

                        SR <= {temp[8:0], SR[7:0], 1'b1};
                    end else begin

                        SR <= {SR[15:8], SR[7:0], 1'b0};
                    end
                    cnt <= cnt + 4'h1;
                end
            end
        end
    end

endmodule

