module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [7:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A[15:8];
        b_reg = B;

        if (a_reg >= b_reg) begin
            result[15:8] = 8'hFF;
            odd[15:8] = a_reg - b_reg;
        end else begin
            result[15:8] = 8'h00;
            odd[15:8] = a_reg;
        end

        odd[7:0] = A[7:0];


        if (odd[15:8] >= b_reg) begin
            result[7:0] = 8'hFF;
            odd[15:8] = odd[15:8] - b_reg;
        end else begin
            result[7:0] = 8'h00;
        end
        odd[7:0] = 8'h00;

    end

endmodule

