assign borrow[0] = 1'b0;


assign borrow[1] = (B[0] | borrow[0]) & ~A[0] | (A[0] & B[0] & borrow[0]);
assign borrow[2] = (B[1] | borrow[1]) & ~A[1] | (A[1] & B[1] & borrow[1]);
assign borrow[3] = (B[2] | borrow[2]) & ~A[2] | (A[2] & B[2] & borrow[2]);
assign borrow[4] = (B[3] | borrow[3]) & ~A[3] | (A[3] & B[3] & borrow[3]);


assign A_less = borrow[4];
assign A_equal = (A == B) && !borrow[4];
assign A_greater = (A != B) && !borrow[4];

