module cla_4bit (
    input [3:1] A,
    input [3:1] B,
    input Cin,
    output [3:1] S,
    output P,
    output G
);
    wire [3:0] P_bit, G_bit;
    assign P_bit = A ^ B;
    assign G_bit = A & B;

    assign P = &P_bit;

    wire [3:0] G_terms;
    assign G_terms[0] = G_bit[0];
    generate
        genvar i;
        for (i = 1;
 i < 4;
 i = i + 1) begin : G_terms_gen
            wire [i-1:0] P_part;
            assign P_part = P_bit[i-1:0];
            assign G_terms[i] = G_bit[i] & (&P_part);
        end
    endgenerate
    assign G = |G_terms;

    reg [4:0] C;
    assign C[0] = Cin;

    generate
        for (i = 0;
 i < 4;
 i = i + 1) begin : carry_gen
            always @(*) begin
                C[i+1] = G_bit[i] | (P_bit[i] & C[i]);
            end
        end
    endgenerate

    assign S = P_bit ^ C[3:1];
endmodule

