module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a + b;
    end else begin

        reg [N-1:0] a_abs, b_abs;
        reg [N-1:0] max_abs, min_abs;
        reg sign;


        a_abs = a[N-1] ? (-a) : a;
        b_abs = b[N-1] ? (-b) : b;

        if (a_abs > b_abs) begin
            max_abs = a_abs;
            min_abs = b_abs;
            sign = a[N-1];
        end else if (b_abs > a_abs) begin
            max_abs = b_abs;
            min_abs = a_abs;
            sign = b[N-1];
        end else begin

            max_abs = 0;
            min_abs = 0;
            sign = 0;
        end

        res = max_abs - min_abs;
        res[N-1] = sign;
    end


    c = res;
end

endmodule

