module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [7:0] exp_temp;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if (a_exponent == 8'hFF || b_exponent == 8'hFF || a_exponent == 0 || b_exponent == 0) begin
                        counter <= 1;
                    end else begin
                        counter <= 1;
                    end
                end

                1: begin

                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        if (a_exponent == 8'hFF && b_exponent != 8'hFF) begin
                            if (a_mantissa != 0 || b_mantissa == 0) begin
                                z <= {a_sign ^ b_sign, 8'hFF, 1'b0, 22'h000001};
                            end else begin
                                z <= {a_sign ^ b_sign, 8'hFF, 22'h000000};
                            end
                        end else if (b_exponent == 8'hFF) begin
                            if (b_mantissa != 0 || a_mantissa == 0) begin
                                z <= {a_sign ^ b_sign, 8'hFF, 1'b0, 22'h000001};
                            end else begin
                                z <= {a_sign ^ b_sign, 8'hFF, 22'h000000};
                            end
                        end else if (a_exponent == 0 && a_mantissa == 0) begin
                            if (b_exponent == 0 && b_mantissa == 0) begin
                                z <= {1'b0, 8'h00, 22'h000000};
                            end else if (b_exponent == 8'hFF || (b_exponent != 0 && b_mantissa != 0)) begin
                                z <= {1'b0, 8'hFF, 22'h000001};
                            end
                        end else if (b_exponent == 0 && b_mantissa == 0) begin
                            z <= {1'b0, 8'hFF, 22'h000001};
                        end
                        counter <= 0;
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        if (a_exponent == 0 && a_mantissa == 0) begin
                            if (b_exponent == 0 && b_mantissa == 0) begin
                                z <= {1'b0, 8'h00, 22'h000000};
                            end else begin
                                z <= {1'b0, b_exponent + 8'hFF, b_mantissa, 9'b0};
                            end
                            counter <= 0;
                        end else if (b_exponent == 0 && b_mantissa == 0) begin
                            z <= {a_sign, 8'hFF, 22'h000001};
                            counter <= 0;
                        end else begin

                            counter <= 2;
                        end
                    end else begin

                        counter <= 2;
                    end
                end

                2: begin

                    reg [23:0] a_mant, b_mant;
                    a_mant = (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mant = (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    product = a_mant * b_mant;
                    counter <= 3;
                end

                3: begin

                    if (product[48]) begin

                        product = product >> 1;
                        exp_temp = a_exponent + b_exponent - 8'd127;
                        exp_temp = exp_temp + 1;
                    end else begin
                        product = product;
                        exp_temp = a_exponent + b_exponent - 8'd127;
                    end
                    counter <= 4;
                end

                4: begin

                    guard_bit = product[22];
                    round_bit = product[21];
                    sticky = |product[20:0];
                    if (guard_bit) begin
                        if (round_bit || sticky) begin
                            z_mantissa = product[48:24] + 1;
                            if (z_mantissa[23]) begin

                                exp_temp = exp_temp + 1;
                                z_mantissa = z_mantissa[23:1];
                            end
                        end else begin

                            if (product[23] == 1'b1) begin
                                z_mantissa = product[48:24];
                            end else begin
                                z_mantissa = product[48:24] + 1;
                                if (z_mantissa[23]) begin
                                    exp_temp = exp_temp + 1;
                                    z_mantissa = z_mantissa[23:1];
                                end
                            end
                        end
                    end else begin
                        z_mantissa = product[48:24];
                    end
                    counter <= 5;
                end

                5: begin

                    if (exp_temp > 8'hFE) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 22'h000000};
                    end else if (exp_temp < 8'h00) begin
                        z <= {a_sign ^ b_sign, 8'h00, 22'h000000};
                    end else begin
                        z <= {a_sign ^ b_sign, exp_temp, z_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

