    input wire wrstn,
    input wire rclk,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire rempty,
    output wire wfull,
    output wire [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);


