wire [ADDR_WIDTH:0] wgray, rgray;


reg [ADDR_WIDTH:0] rgray_sync1, rgray_sync2;
reg [ADDR_WIDTH:0] wgray_sync1, wgray_sync2;


function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
    reg [ADDR_WIDTH:0] bin;
    integer i;
    begin
        bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
        for (i = ADDR_WIDTH-1;
 i >= 0;
 i = i - 1) begin
            bin[i] = bin[i+1] ^ gray[i];
        end
        gray2bin = bin;
    end
endfunction


wire [ADDR_WIDTH:0] rptr_bin_sync = gray2bin(rgray_sync2);
wire [ADDR_WIDTH:0] wptr_bin_sync = gray2bin(wgray_sync2);


assign wfull = ( (wptr_bin - rptr_bin_sync) >= DEPTH );
assign rempty = ( rptr_bin == wptr_bin_sync );


wire wen = winc && !wfull;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else if (wen) begin
        wptr_bin <= wptr_bin + 1;
    end
end


wire ren = rinc && !rempty;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else if (ren) begin
        rptr_bin <= rptr_bin + 1;
    end
end


assign wgray = wptr_bin ^ (wptr_bin >> 1);
assign rgray = rptr_bin ^ (rptr_bin >> 1);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rgray_sync1 <= 0;
        rgray_sync2 <= 0;
    end else begin
        rgray_sync1 <= rgray;
        rgray_sync2 <= rgray_sync1;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wgray_sync1 <= 0;
        wgray_sync2 <= 0;
    end else begin
        wgray_sync1 <= wgray;
        wgray_sync2 <= wgray_sync1;
    end
end


