module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    localparam idle      = 2'b00;
    localparam s1_red    = 2'b01;
    localparam s2_yellow = 2'b10;
    localparam s3_green  = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt, cnt_next;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) cnt <= 10;
        else cnt <= cnt_next;
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= idle;
        else state <= next_state;
    end


    always @(*) begin
        case (state)
            idle:     next_state = s1_red;
            s1_red:   next_state = (cnt == 0) ? s2_yellow : s1_red;
            s2_yellow: next_state = (cnt == 0) ? s3_green : s2_yellow;
            s3_green: next_state = (cnt == 0) ? s1_red : s3_green;
            default:  next_state = idle;
        endcase
    end


    always @(*) begin
        case (state)
            idle:     cnt_next = 10;
            s1_red:   cnt_next = (cnt == 0) ? 5 : cnt - 1;
            s2_yellow: cnt_next = (cnt == 0) ? 60 : cnt - 1;
            s3_green: begin
                if (pass_request && cnt > 10)
                    cnt_next = 10;
                else if (cnt == 0)
                    cnt_next = 10;
                else
                    cnt_next = cnt - 1;
            end
            default:  cnt_next = 10;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b000;
            clock <= 10;
        end else begin
            {red, yellow, green} <= {state != s3_green, state != s1_red, state == s3_green};
            clock <= cnt;
        end
    end

endmodule

