module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [1:0] state;
reg [16:0] SR;

reg [7:0] divisor_abs;
reg [7:0] dividend_abs;
reg dividend_sign;
reg divisor_sign;
reg [3:0] cnt;

localparam IDLE = 0;
localparam DIVIDE = 1;
localparam ADJUST = 2;
localparam DONE = 3;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        dividend_sign <= dividend[7];
                        divisor_sign <= divisor[7];
                        dividend_abs <= dividend[7] ? -dividend : dividend;
                        divisor_abs <= divisor[7] ? -divisor : divisor;
                    end else begin
                        dividend_abs <= dividend;
                        divisor_abs <= divisor;
                        dividend_sign <= 0;
                        divisor_sign <= 0;
                    end

                    SR <= { (dividend_abs << 1), 8'b0 };
                    cnt <= 0;
                    state <= DIVIDE;
                end
            end
            DIVIDE: begin
                if (cnt < 8) begin

                    if (SR[16:8] >= divisor_abs) begin
                        SR[16:8] <= SR[16:8] - divisor_abs;
                        SR[7:0] <= {SR[6:0], 1'b1};
                    end else begin
                        SR[16:8] <= SR[16:8] + divisor_abs;
                        SR[7:0] <= {SR[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin
                    state <= ADJUST;
                end
            end
            ADJUST: begin

                if (sign) begin
                    reg [7:0] q = SR[7:0];
                    reg [7:0] r = SR[16:8];
                    if (dividend_sign ^ divisor_sign) q = -q;
                    if (dividend_sign) r = -r;
                    result <= {r, q};
                end else begin
                    result <= {SR[16:8], SR[7:0]};
                end
                state <= DONE;
                res_valid <= 1;
            end
            DONE: begin
                if (res_valid) begin
                    res_valid <= 0;
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

