module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        reg [15:0] quotient = 0;
        reg [15:0] remainder = 0;
        integer i;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = remainder << 1;
            if (i < 16) remainder[0] = a_reg[i];

            if (remainder >= {8'b0, b_reg}) begin
                remainder = remainder - {8'b0, b_reg};
                quotient = (quotient << 1) | 1'b1;
            end else begin
                quotient = quotient << 1;
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

