module fixed_point_adder #(
    parameter Q = 8, 
    parameter N = 32 
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);


    reg [N-1:0] res;

    always @(*) begin

        if (a[N-1] == b[N-1]) begin
            res = a + b;
        end

        else begin

            reg [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
            reg [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = a[N-1];
            end
            else if (abs_b > abs_a) begin
                res = abs_b - abs_a;
                res[N-1] = b[N-1];
            end
            else begin
                res = 0;
            end
        end


        c = res;
    end

endmodule

