module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_res;
    reg [N-1:0] result_signed;
    reg [N-2:0] mag_result;

    always @(*) begin

        result_signed = $signed(a) - $signed(b);


        sign_res = result_signed[N-1];


        mag_result = sign_res ? (~result_signed + 1) : result_signed;


        mag_result = mag_result[N-2:0];


        mag_result = mag_result << (Q);


        c = {sign_res, mag_result[N-2:0]};


        if (mag_result == 0)
            c[N-1] = 0;
    end

endmodule

