module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg [9:0] combined_exponent;
    reg a_sign, b_sign, z_sign;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;


    function is_nan(input [31:0] num);
        is_nan = (num[30:23] == 8'hFF) && (num[22:0] != 0);
    endfunction


    function is_inf(input [31:0] num);
        is_inf = (num[30:23] == 8'hFF) && (num[22:0] == 0);
    endfunction


    function is_zero(input [31:0] num);
        is_zero = (num[30:23] == 8'h00) && (num[22:0] == 0);
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            combined_exponent <= 0;
            product <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};


                    if (is_nan(a) || is_nan(b)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        counter <= 3'b111;
                    end else if (is_inf(a) || is_inf(b)) begin
                        if (is_zero(b) || is_zero(a)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        counter <= 3'b111;
                    end else if (is_zero(a) || is_zero(b)) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 3'b111;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        combined_exponent <= a[30:23] + b[30:23] - 127;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    if (product[47:46] >= 2'b10) begin
                        product <= product >> 1;
                        combined_exponent <= combined_exponent + 1;
                    end
                    counter <= 3'b010;
                end

                3'b010: begin

                    if (product[47:46] >= 2'b10) begin
                        {z_mantissa, guard_bit, round_bit} = {product[46:24], product[23], product[22]};
                        sticky = |product[21:0];
                    end else begin
                        {z_mantissa, guard_bit, round_bit} = {product[45:23], product[22], product[21]};
                        sticky = |product[20:0];
                    end
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (guard_bit) begin
                        if (round_bit | sticky | z_mantissa[0]) begin
                            z_mantissa = z_mantissa + 1;
                        end else begin
                            if (z_mantissa == 23'h7FFFFF) begin
                                z_mantissa = 23'h0;
                                combined_exponent = combined_exponent + 1;
                            end
                        end
                    end
                    counter <= 3'b100;
                end

                3'b100: begin

                    if (combined_exponent >= 8'hFF) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (combined_exponent <= 8'h00) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, combined_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

