            wgray_sync1 <= wgray;
            wgray_sync <= wgray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty <= 1;
        end else begin
            rempty <= (rgray == wgray_sync);
