module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] count;

    always @(posedge Clk) begin
        if (Rst) begin
            count <= 0;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else if (EN) begin
            if (!RW) begin 
                if (count < 4) begin
                    stack_mem[count] <= dataIn;
                    count <= count + 1;
                end
            end else begin 
                if (count > 0) begin
                    dataOut <= stack_mem[count-1];
                    stack_mem[count-1] <= 4'b0;
                    count <= count - 1;
                end
            end
        end
    end

    assign EMPTY = (count == 0);
    assign FULL = (count == 4);

endmodule

