module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 0,
              s1_red = 1,
              s2_yellow = 2,
              s3_green = 3;

    reg [7:0] cnt;
    reg [1:0] state;

    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                end
                s1_red: begin
                    red <= 1;
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                        red <= 0;
                        green <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    green <= 1;
                    if (pass_request && (cnt > 10)) begin
                        cnt <= 10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 5;
                        green <= 0;
                        yellow <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    yellow <= 1;
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
                        yellow <= 0;
                        red <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
            endcase
        end
    end

    assign clock = cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end

endmodule

