module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);


reg [7:0] abs_dividend, abs_divisor;
reg original_sign_dividend, original_sign_divisor;
reg [15:0] SR;

reg [7:0] NEG_DIVISOR;
reg [3:0] cnt;
reg start_cnt;

localparam IDLE = 0;
localparam BUSY = 1;
reg state;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        original_sign_dividend <= 0;
        original_sign_divisor <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin
                    original_sign_dividend <= dividend[7];
                    original_sign_divisor <= divisor[7];
                    if (sign) begin
                        abs_dividend <= (dividend[7]) ? -dividend : dividend;
                        abs_divisor <= (divisor[7]) ? -divisor : divisor;
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                    end
                    SR <= {8'b0, (abs_dividend << 1)};

                    NEG_DIVISOR <= -abs_divisor;
                    cnt <= 4'd1;
                    start_cnt <= 1;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (start_cnt) begin
                    if (cnt < 8) begin

                        {carry_out, temp_remainder} = {1'b0, SR[15:8]} + {1'b0, abs_divisor};

                        SR <= {temp_remainder, SR[7:0], carry_out};
                        cnt <= cnt + 1;
                    end else begin

                        if (sign) begin
                            if (original_sign_dividend)
                                result[15:8] <= -SR[15:8];

                            else
                                result[15:8] <= SR[15:8];

                            if (original_sign_dividend ^ original_sign_divisor)
                                result[7:0] <= -SR[7:0];

                            else
                                result[7:0] <= SR[7:0];
                        end else begin
                            result <= {SR[15:8], SR[7:0]};
                        end
                        res_valid <= 1;
                        state <= IDLE;
                        cnt <= 0;
                        start_cnt <= 0;
                    end
                end
            end
        endcase
    end
end

endmodule

