    reg [2*size-1:0] sum_stage2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_stage1 <= 0;
            sum_stage2 <= 0;
        end else begin
            sum_stage1 <= pp[0] + pp[1];
            sum_stage2 <= pp[2] + pp[3];
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out <= 0;
        end else begin
            mul_out <= sum_stage1 + sum_stage2;
        end
    end

