module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G_group,
    output P_group
);
    wire [16:1] G, P;
    wire [16:1] G_prev, P_prev;

    assign G = A & B;
    assign P = A ^ B;


    assign G_prev[0] = 0;
    assign P_prev[0] = 0;

    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gp_calc
            assign G_prev[i] = G_prev[i-1] | (P_prev[i-1] & G[i-1]);
            assign P_prev[i] = P_prev[i-1] & P[i-1];
        end
    endgenerate


    wire [16:1] C;
    assign C[0] = C_in;

    generate
        for (i = 1;
 i <= 16;
 i = i + 1) begin : carry_calc
            assign C[i] = G_prev[i-1] | (P_prev[i-1] & C[0]);
        end
    endgenerate


    assign S = P ^ C[16:1];


    assign G_group = G_prev[16];
    assign P_group = P_prev[16];
endmodule

