module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);
    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [22:0] z_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};
                        counter <= 0;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin
                        if ((a_exponent == 8'hff && a_mantissa == 0) && 
                            (b_exponent == 8'hff && b_mantissa == 0)) begin
                            z <= {1'b0, 8'hff, 23'h1};
                        end else if (a_exponent == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (b_exponent == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin
                            z <= { (a_sign ^ b_sign), 31'b0 };
                        end
                        counter <= 0;
                    end else if ((a_exponent == 0 && a_mantissa == 0) || 
                                (b_exponent == 0 && b_mantissa == 0)) begin
                        if ( (a_exponent == 0 && a_mantissa == 0) && 
                             (b_exponent == 0 && b_mantissa == 0) ) begin
                            z <= { (a_sign ^ b_sign), 31'b0 };
                        end else begin
                            z <= { (a_sign ^ b_sign), 31'b0 };
                        end
                        counter <= 0;
                    end else begin
                        counter <= 1;
                    end
                end
                1: begin

                    reg [23:0] a_mantissa_full, b_mantissa_full;
                    a_mantissa_full = (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_full = (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    product <= a_mantissa_full * b_mantissa_full;
                    counter <= 2;
                end
                2: begin

                    reg [47:0] normalized;
                    reg [7:0] exp_adj;
                    case (product[47:46])
                        2'b00: begin

                            integer i;
                            reg [45:0] frac = product[45:0];
                            for (i=45;
 i>=0;
 i=i-1) begin
                                if (frac[i]) break;
                            end
                            normalized = {frac[i], frac[i-1:0], {(45-i){1'b0}}} << (45 - i);
                            exp_adj = 8'( -127 ) - (45 - i + 1);

