module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,

    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output reg [WIDTH-1:0] rdata,

    output wire rempty,
    output wire wfull
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    reg [ADDR_WIDTH:0] waddr_bin, raddr_bin;

    reg [ADDR_WIDTH:0] waddr_gray, raddr_gray;

    reg [ADDR_WIDTH:0] waddr_gray_sync0, waddr_gray_sync1;

    reg [ADDR_WIDTH:0] raddr_gray_sync0, raddr_gray_sync1;



    function [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] bin);
        bin2gray = bin ^ (bin >> 1);
    endfunction


    function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
        reg [ADDR_WIDTH:0] bin;
        integer i;
        begin
            bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
            for (i = ADDR_WIDTH-1;
 i >= 0;
 i = i-1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end


    always @(posedge wclk) begin
        if (!wrstn)
            waddr_gray <= 0;
        else
            waddr_gray <= bin2gray(waddr_bin);
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            {waddr_gray_sync0, waddr_gray_sync1} <= 0;
        end else begin
            waddr_gray_sync0 <= waddr_gray;
            waddr_gray_sync1 <= waddr_gray_sync0;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end


    always @(posedge rclk) begin
        if (!rrstn)
            raddr_gray <= 0;
        else
            raddr_gray <= bin2gray(raddr_bin);
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            {raddr_gray_sync0, raddr_gray_sync1} <= 0;
        end else begin
            raddr_gray_sync0 <= raddr_gray;
            raddr_gray_sync1 <= raddr_gray_sync0;
        end
    end


    assign rempty = (raddr_gray == raddr_gray_sync1);
    assign wfull = (waddr_gray[ADDR_WIDTH] != raddr_gray_sync1[ADDR_WIDTH]) &&
                   (waddr_gray[ADDR_WIDTH-1] != raddr_gray_sync1[ADDR_WIDTH-1]) &&
                   (waddr_gray[ADDR_WIDTH-2:0] == raddr_gray_sync1[ADDR_WIDTH-2:0]);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );

endmodule


