module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [1:0] cnt;
reg [3:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b0;
        shift_reg <= 4'b0;
        dout <= 0;
        valid_out <= 0;
    end else begin
        case (cnt)
            2'b00: begin

                shift_reg <= d;
                dout <= d[3];
                valid_out <= 1;
                cnt <= cnt + 1;
            end
            2'b01: begin

                dout <= shift_reg[2];
                shift_reg <= shift_reg << 1;
                valid_out <= 0;
                cnt <= cnt + 1;
            end
            2'b10: begin

                dout <= shift_reg[1];
                shift_reg <= shift_reg << 1;
                valid_out <= 0;
                cnt <= cnt + 1;
            end
            2'b11: begin

                dout <= shift_reg[0];
                shift_reg <= shift_reg << 1;
                valid_out <= 0;
                cnt <= 0;
            end
        endcase
    end
end

endmodule

