module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
        end else begin
            case (state)
                S0: state <= (data_in == 1'b0) ? S1 : S0;
                S1: state <= (data_in == 1'b1) ? S2 : S0;
                S2: state <= (data_in == 1'b0) ? S0 : S0;
                default: state <= S0;
            endcase
        end
    end

    always @(*) begin
        case (state)
            S2: data_out = (data_in == 1'b0) ? 1'b1 : 1'b0;
            default: data_out = 1'b0;
        endcase
    end

endmodule

