module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    reg state;
    reg [4:0] next_wave;
    reg next_state;

    always @(*) begin
        case (state)
            0: begin
                next_wave = wave + 1;
                if (next_wave == 5'b11111)
                    next_state = 1;
                else
                    next_state = 0;
            end
            1: begin
                next_wave = wave - 1;
                if (next_wave == 5'b0)
                    next_state = 0;
                else
                    next_state = 1;
            end
            default: begin
                next_wave = wave;
                next_state = state;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wave <= 0;
            state <= 0;
        end else begin
            wave <= next_wave;
            state <= next_state;
        end
    end

