module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [7:0] divisor_abs;
    reg dividend_sign;
    reg divisor_sign;
    reg processing;
    reg [3:0] cnt;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            divisor_abs <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            result <= 0;
        end else begin
            if (res_valid) begin
                if (!opn_valid) begin
                    res_valid <= 0;
                end
            end else if (opn_valid && !processing) begin
                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                end else begin
                    dividend_sign <= 0;
                    divisor_sign <= 0;
                    divisor_abs <= divisor;
                end
                remainder <= 0;
                quotient <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                cnt <= 0;
                processing <= 1;
            end

            if (processing) begin
                if (cnt < 8) begin
                    reg [7:0] temp_remainder;
                    temp_remainder = {remainder[6:0], quotient[7]};
                    if (temp_remainder >= divisor_abs) begin
                        remainder <= temp_remainder - divisor_abs;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        remainder <= temp_remainder;
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin
                    processing <= 0;
                    res_valid <= 1;
                    if (sign) begin
                        if (dividend_sign ^ divisor_sign) begin
                            quotient <= -quotient;
                        end
                        if (dividend_sign) begin
                            remainder <= -remainder;
                        end
                    end
                    result <= {remainder, quotient};
                end
            end
        end
    end

endmodule

