        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        integer i;
        rem = 16'b0;
        quo = 16'b0;
        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = {rem[14:0], a_reg[i]};
            if (rem >= {8'b0, b_reg}) begin
                rem = rem - {8'b0, b_reg};
                quo[i] = 1'b1;
            end else begin
                quo[i] = 1'b0;
            end
        end
    end

    assign result = quo;
    assign odd = rem;
endmodule

