module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] abs_a, abs_b;
    reg res_sign;
    reg [N-1:0] sum;
    reg [N-1:0] difference;

    always @(*) begin

        abs_a = a[N-1] ? (~a + 1) : a;
        abs_b = b[N-1] ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            sum = abs_a + abs_b;
            res_sign = a[N-1];

            if (sum[N-1] != res_sign) begin
                sum = res_sign ? {1'b1, {(N-1){1'b0}}} : {1'b0, {(N-1){1'b1}}};
            end
            c = {sum[N-1], sum[N-2:0]};
        end else begin

            if (abs_a > abs_b) begin
                difference = abs_a - abs_b;
                res_sign = a[N-1];
            end else if (abs_b > abs_a) begin
                difference = abs_b - abs_a;
                res_sign = b[N-1];
            end else begin
                difference = 0;
                res_sign = 0;
            end
            c = {res_sign, difference[N-2:0]};
        end
    end

endmodule

