reg [ADDR_GRAY_WIDTH-1:0] wgray_sync_rclk1, wgray_sync_rclk2;

function [ADDR_GRAY_WIDTH-1:0] bin2gray(input [ADDR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

function [ADDR_WIDTH-1:0] gray2bin(input [ADDR_GRAY_WIDTH-1:0] gray);
    reg [ADDR_WIDTH-1:0] bin;
    integer i;
    begin
        bin[ADDR_WIDTH-1] = gray[ADDR_GRAY_WIDTH-1];
        for (i = ADDR_GRAY_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end

always @(posedge wclk) begin
    wgray <= bin2gray(waddr_bin);
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        {rgray_sync_wclk2, rgray_sync_wclk1} <= 0;
    end else begin
        {rgray_sync_wclk2, rgray_sync_wclk1} <= {rgray_sync_wclk1, rgray};
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

always @(posedge rclk) begin
    rgray <= bin2gray(raddr_bin);
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        {wgray_sync_rclk2, wgray_sync_rclk1} <= 0;
    end else begin
        {wgray_sync_rclk2, wgray_sync_rclk1} <= {wgray_sync_rclk1, wgray};
    end
end

wire [ADDR_WIDTH-1:0] raddr_bin_sync = gray2bin(rgray_sync_wclk2);
wire [ADDR_WIDTH-1:0] waddr_bin_sync = gray2bin(wgray_sync_rclk2);

wire full_condition = (wgray[ADDR_GRAY_WIDTH-1] ^ wgray[ADDR_GRAY_WIDTH-2]) && 
                      (wgray[ADDR_GRAY_WIDTH-3:0] == raddr_bin_sync[ADDR_GRAY_WIDTH-3:0]) &&
                      (wgray == bin2gray(raddr_bin_sync));

wire empty_condition = (wgray == rgray);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wfull <= 0;
    end else begin
        wfull <= full_condition;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rempty <= 1;
    end else begin
        rempty <= empty_condition;
    end
end

