module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 0,
              s1_red = 1,
              s2_yellow = 2,
              s3_green = 3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg prev_red, prev_yellow, prev_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: begin
                next_state = (cnt == 3) ? s3_green : s1_red;
            end
            s3_green: begin
                next_state = (cnt == 60) ? s2_yellow : s3_green;
            end
            s2_yellow: begin
                next_state = (cnt == 5) ? s1_red : s2_yellow;
            end
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green && cnt > 10)
                cnt <= 10;
            else if (prev_green && !green)
                cnt <= 60;
            else if (prev_yellow && !yellow)
                cnt <= 5;
            else if (prev_red && !red)
