module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state;
    reg [7:0] dividend_reg;
    reg [7:0] divisor_reg;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg dividend_sign;
    reg divisor_sign;
    reg [15:0] sr;
    reg [3:0] count;
    reg [7:0] quotient;
    reg [7:0] remainder;


    function [7:0] abs_signed;
        input [7:0] value;
        reg signed [7:0] signed_value;
        begin
            signed_value = $signed(value);
            abs_signed = (signed_value < 0) ? -signed_value : signed_value;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            sr <= 0;
            count <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid && !res_valid) begin

                        dividend_reg <= dividend;
                        divisor_reg <= divisor;
                        if (sign) begin
                            dividend_sign <= dividend[7];
                            divisor_sign <= divisor[7];
                            abs_dividend <= abs_signed(dividend);
                            abs_divisor <= abs_signed(divisor);
                        end else begin
                            dividend_sign <= 0;
                            divisor_sign <= 0;
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                        end
                        sr <= {8'b0, abs_dividend};
                        count <= 8;
                        state <= BUSY;
                    end
                end

                BUSY: begin
                    if (count > 0) begin

                        sr <= sr << 1;

                        if (sr[15:8] >= abs_divisor) begin
                            sr[15:8] <= sr[15:8] - abs_divisor;
                            sr[0] <= 1;
                        end else begin
                            sr[0] <= 0;
                        end
                        count <= count - 1;
                    end else begin

                        quotient <= sr[7:0];
                        remainder <= sr[15:8];

                        if (sign) begin
                            quotient <= (dividend_sign ^ divisor_sign) ? -quotient : quotient;
                            remainder <= dividend_sign ? (~remainder + 1) : remainder;
                        end
                        result <= {remainder, quotient};
                        state <= DONE;
                        res_valid <= 1;
                    end
                end

                DONE: begin
                    res_valid <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

