module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg, b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        integer i;
        reg [15:0] rem;
        reg [15:0] quo;

        rem = 16'b0;
        quo = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | ((a_reg >> i) & 1);
            if (rem >= b_reg) begin
                quo[i] = 1;
                rem = rem - b_reg;
            end else begin
                quo[i] = 0;
            end
        end

        result = quo;
        odd = rem;
    end

endmodule

