module fixed_point_adder #(parameter Q=2, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg res_sign;

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-1:0] mag_a = sign_a ? (~a + 1) : a;
wire [N-1:0] mag_b = sign_b ? (~b + 1) : b;

always @(*) begin
    if (sign_a == sign_b) begin
        res = mag_a + mag_b;
        res_sign = sign_a;

        if ((sign_a && !res[N-1]) || (!sign_a && res[N-1])) begin
            res = 0;
        end
    end else begin
        if (mag_a >= mag_b) begin
            res = mag_a - mag_b;
            res_sign = sign_a;
        end else begin
            res = mag_b - mag_a;
            res_sign = sign_b;
        end
    end
    c = {res_sign, res[N-2:0]};
end

endmodule

