module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [9:0] sum_exponent;
reg [47:0] product;
reg [23:0] product_mantissa;
reg guard, round, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                    if (a_exponent != 0 || b_exponent != 0) begin
                        if (a_exponent == 0 && b_exponent == 0) begin
                            if (a_mantissa != 0 || b_mantissa != 0)
                                z <= {1'b0, 8'hFF, 23'h1};

                            else
                                z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        end
                    end
                end else if (a_exponent == 0 || b_exponent == 0) begin
                    if (a_exponent == 0 && b_exponent == 0) begin
                        if (a_mantissa == 0 || b_mantissa == 0)
                            z <= {a_sign ^ b_sign, 31'h0};

                        else
                            z <= {1'b0, 8'hFF, 23'h1};

                    end else begin
                        if (a_exponent == 0)
                            z <= {b_sign ^ a_sign, 31'h0};
                        else
                            z <= {a_sign ^ b_sign, 31'h0};
                    end
                end else begin
                    sum_exponent <= a_exponent + b_exponent - 8'd127;
                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    counter <= 1;
                end
            end

            1: begin

                if (product[47:46] >= 2) begin
                    product <= {1'b0, product[47:1]};
                    sum_exponent <= sum_exponent + 1;
                end
                product_mantissa <= {1'b1, product[45:23]};
                guard <= product[22];
                round <= product[21];
                sticky <= |product[20:0];
                counter <= 2;
            end

            2: begin

                if (guard) begin
                    if (round || sticky)
                        product_mantissa <= product_mantissa + 1;
                    if (product_mantissa[23]) begin
                        product_mantissa <= product_mantissa >> 1;
                        sum_exponent <= sum_exponent + 1;
                    end
                end


                if (sum_exponent >= 255)
                    z <= {product_mantissa[23], 8'hFF, 23'h0};

                else if (sum_exponent <= 0)
                    z <= {product_mantissa[23], 31'h0};

                else
                    z <= {product_mantissa[23], sum_exponent[7:0], product_mantissa[22:0]};

                counter <= 0;
            end

            default: counter <= 0;
        endcase
    end
end

endmodule

