        FULL <= 0;

        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
    end
    else if (EN) begin
        case (RW)
            0: begin 
                if (!FULL) begin
                    stack_mem[SP-1] <= dataIn;
                    SP <= SP - 1;
                end
            end
            1: begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP-1];
                    stack_mem[SP-1] <= 0;

                    SP <= SP + 1;
                end
            end
        endcase
    end

    EMPTY <= (SP == 4);
    FULL <= (SP == 0);
end

endmodule

