module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend, abs_divisor;
    reg sign_dividend, sign_divisor;
    reg [16:0] SR;

    reg [3:0] counter;
    reg processing;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            counter <= 0;
            processing <= 0;
            result <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
                counter <= 0;
                processing <= 0;
            end else if (opn_valid && !res_valid && !processing) begin

                if (sign) begin
                    sign_dividend <= dividend[7];
                    sign_divisor <= divisor[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    sign_dividend <= 0;
                    sign_divisor <= 0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                end

                SR <= {9'b0, abs_dividend} << 1;
                counter <= 0;
                processing <= 1;
            end else if (processing) begin
                if (counter < 8) begin

                    reg [8:0] temp_remainder = SR[16:8] - {1'b0, abs_divisor};
                    if (temp_remainder[8]) begin 
                        SR[16:8] <= temp_remainder;
                        SR[7:0] <= {SR[7:0], 1'b1};
                    end else begin 
                        SR[16:8] <= temp_remainder + {1'b0, abs_divisor};
                        SR[7:0] <= {SR[7:0], 1'b0};
                    end
                    SR <= SR << 1;

                    counter <= counter + 1;
                end else begin 
                    processing <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        reg [7:0] signed_remainder = sign_dividend ? -SR[16:9] : SR[16:9];
                        reg [7:0] signed_quotient = (sign_dividend ^ sign_divisor) ? -SR[7:0] : SR[7:0];
                        result <= {signed_remainder, signed_quotient};
                    end else begin
                        result <= {SR[16:9], SR[7:0]};
                    end
                end
            end
        end
    end
endmodule

