    if (!rst_n) begin
        count <= 0;
        temp_sum <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        valid_out <= 0;
        if (valid_in) begin
            if (count == 2'b11) begin

                data_out <= temp_sum + {2'b00, data_in};
                valid_out <= 1;

                count <= 0;
                temp_sum <= {2'b00, data_in};
            end else begin

                temp_sum <= temp_sum + {2'b00, data_in};
                count <= count + 1;
            end
        end
    end
end

endmodule

