    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];

    always @(*) begin
        if (a_sign == b_sign) begin

            res = a - b;
        end else begin

            reg [N-1:0] a_abs = a_sign ? (~a + 1) : a;
            reg [N-1:0] b_abs = b_sign ? (~b + 1) : b;
            reg [N-1:0] mag_diff;

            if (a_abs > b_abs) begin
                mag_diff = a_abs - b_abs;
                res = {1'b0, mag_diff[N-2:0]};
            end else if (b_abs > a_abs) begin
                mag_diff = b_abs - a_abs;
                res = {1'b1, mag_diff[N-2:0]};
            end else begin

                res = {1'b0, {(N-1){1'b0}}};
            end
        end


        if (res == 0)
            c = 0;
        else
            c = res;
    end

endmodule

