    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 1;
                end
                1: begin

                    if (a_exponent == 255 || b_exponent == 255) begin
                        z_sign <= a_sign ^ b_sign;
                        if (a_exponent == 255 ^ b_exponent == 255) begin

                            z_exponent <= 255;
                            z_mantissa <= 1;
                        end else begin

                            z_exponent <= 255;
                            z_mantissa <= 0;
                        end
