                                b_exponent == 0 && b_mantissa == 0) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 127;
                        counter <= 2;
                    end
                end
                2: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];

                    z_mantissa <= product[46:24] + 
                                (guard_bit & (round_bit | sticky | product[24]));
                    counter <= 3;
                end
                3: begin

                    if (z_exponent > 254) begin
                        z_exponent <= 255;
                        z_mantissa <= 0;
                    end else if (z_exponent < 1) begin
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end

                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

