module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output reg wfull,
    output reg rempty,
    output [WIDTH-1:0] rdata
);

localparam DEPTH_PTR = $clog2(DEPTH) + 1;

reg [DEPTH_PTR-1:0] wptr, rptr;
reg [DEPTH_PTR-1:0] wptr_gray, rptr_gray;
reg [DEPTH_PTR-1:0] rptr_gray_sync [1:0];
reg [DEPTH_PTR-1:0] wptr_gray_sync [1:0];
wire [DEPTH_PTR-1:0] rptr_sync_bin, wptr_sync_bin;

dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram_inst (
    .wclk(wclk),
    .wenc(wfull ? 0 : 1),
    .waddr(wptr[$clog2(DEPTH)-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rempty ? 0 : 1),
    .raddr(rptr[$clog2(DEPTH)-1:0]),
    .rdata(rdata)
);

gray2bin #(.WIDTH(DEPTH_PTR)) g2b_r (.gray(rptr_gray_sync[1]), .bin(rptr_sync_bin));
gray2bin #(.WIDTH(DEPTH_PTR)) g2b_w (.gray(wptr_gray_sync[1]), .bin(wptr_sync_bin));


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        wptr <= wptr + 1;
        wptr_gray <= (wptr + 1) ^ ((wptr + 1) >> 1);
    end else begin
        wptr_gray <= wptr ^ (wptr >> 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
        rptr_gray <= 0;
    end else if (rinc && !rempty) begin
        rptr <= rptr + 1;
        rptr_gray <= (rptr + 1) ^ ((rptr + 1) >> 1);
    end else begin
        rptr_gray <= rptr ^ (rptr >> 1);
    end
end


always @(posedge wclk) rptr_gray_sync[1:0] <= {rptr_gray_sync[0], rptr_gray};
always @(posedge rclk) wptr_gray_sync[1:0] <= {wptr_gray_sync[0], wptr_gray};


always @(posedge wclk) wfull <= (wptr - rptr_sync_bin >= DEPTH);
always @(posedge rclk) rempty <= (wptr_sync_bin == rptr);

function [DEPTH_PTR-1:0] gray(input [DEPTH_PTR-1:0] bin);
    gray = (bin >> 1) ^ bin;
endfunction

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] mem [0:DEPTH-1];

always @(posedge wclk) if (wenc) mem[waddr] <= wdata;
always @(posedge rclk) if (renc) rdata <= mem[raddr];

endmodule

module gray2bin #(
    parameter WIDTH = 5
) (
    input [WIDTH-1:0] gray,
    output [WIDTH-1:0] bin
);

assign bin[WIDTH-1] = gray[WIDTH-1];
generate
    genvar i;
    for (i = WIDTH-2;
 i >= 0;
 i = i - 1) begin : gray2bin
        assign bin[i] = gray[i] ^ bin[i+1];
    end
endgenerate

endmodule

