module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [3:0] data_reg;
    reg [1:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 4'b0;
            cnt <= 2'b11;
            valid_out <= 0;
            dout <= 0;
        end else begin
            if (cnt == 3) begin
                data_reg <= d;
                cnt <= 0;
                valid_out <= 1;
                dout <= d[3];
            end else begin
                data_reg <= {data_reg[2:0], data_reg[3]};
                cnt <= cnt + 1;
                valid_out <= 0;
                dout <= data_reg[2];
            end
        end
    end

endmodule

