module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'h0A;

            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 8'h02;

                    red <= 1;
                    green <= 0;
                    yellow <= 0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 8'h3B;

                        green <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && (cnt > 8'h0A)) begin
                        cnt <= cnt - 8'h0A - 1;

                    end else if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 8'h04;

                        yellow <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                    green <= (cnt != 0);
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 8'h02;

                        red <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                    yellow <= (cnt != 0);
                end
                default: begin
                    state <= idle;
                    cnt <= 8'h0A;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

