module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] remainder, quotient;
    reg [8:0] sr;

    reg [7:0] neg_divisor;
    reg [3:0] cnt;
    reg start_cnt;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            neg_divisor <= 0;
            sr <= 0;
            remainder <= 0;
            quotient <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_reg <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_reg <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                neg_divisor <= -divisor_reg;

                sr <= {dividend_reg, 1'b0};

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 0;
                    cnt <= 0;
                    remainder <= sr[8:1];

                    quotient <= {1'b0, sr[0]};



                    if (sign) begin
                        remainder <= dividend[7] ? -remainder : remainder;
                        if (dividend[7] ^ divisor[7]) quotient <= -quotient;
                    end

                    result <= {remainder, quotient};
                    res_valid <= 1;
                end else begin

                    reg [8:0] sub_result = {1'b0, sr[8:1]} - {1'b0, neg_divisor};
                    if (sub_result[8] == 0) begin 
                        sr <= {sub_result[7:0], sr[0], 1'b1};

                    end else begin 
                        sr <= {sr[8:1], sr[0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end


            if (opn_valid && !start_cnt) begin
                res_valid <= 0;
            end
        end
    end

endmodule

