module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);


    wire borrow_out_0, borrow_out_1, borrow_out_2, borrow_out_3;


    assign borrow_out_0 = (B[0] & ~A[0]);


    assign borrow_out_1 = (B[1] & ~A[1]) | (borrow_out_0 & (B[1] | ~A[1]));


    assign borrow_out_2 = (B[2] & ~A[2]) | (borrow_out_1 & (B[2] | ~A[2]));


    assign borrow_out_3 = (B[3] & ~A[3]) | (borrow_out_2 & (B[3] | ~A[3]));


    wire [3:0] D;
    assign D[0] = A[0] ^ B[0];
    assign D[1] = A[1] ^ B[1] ^ borrow_out_0;
    assign D[2] = A[2] ^ B[2] ^ borrow_out_1;
    assign D[3] = A[3] ^ B[3] ^ borrow_out_2;


    wire D_all_zero = ~(|D);


    assign A_less = borrow_out_3;
    assign A_equal = (borrow_out_3 == 0) && D_all_zero;
    assign A_greater = (borrow_out_3 == 0) && ~D_all_zero;

