module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input cin,
    output [15:0] S,
    output G_group,
    output P_group
);
    wire [15:0] G = A & B;
    wire [15:0] P = A ^ B;


    wire [15:0] G_terms;
    wire [15:0] P_terms;

    assign G_terms[0] = G[0];
    assign P_terms[0] = P[0];

    genvar i;
    generate
        for (i = 1;
 i < 16;
 i = i + 1) begin : gen_terms
            assign G_terms[i] = G[i] | (P[i] & G_terms[i-1]);
            assign P_terms[i] = P[i] & P_terms[i-1];
        end
    endgenerate

    assign G_group = G_terms[15];
    assign P_group = P_terms[15];


    wire [16:0] C;
    assign C[0] = cin;

    genvar j;
    generate
        for (j = 0;
 j < 16;
 j = j + 1) begin : carry_gen
            assign C[j+1] = G[j] | (P[j] & C[j]);
        end
    endgenerate


    assign S = P ^ C[15:0];
