module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_mant, b_mant;
reg [47:0] product;
reg guard, round, sticky;
reg [23:0] product_shifted;
reg [7:0] sum_exponent;
reg [24:0] mantissa_rounded;
reg round_up;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];
                counter <= 1;
            end
            1: begin

                if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                    if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin

                        if (a[22:0] == 0 && b[22:0] == 0) begin
                            z_sign <= a_sign ^ b_sign;
                            z <= {z_sign, 8'hFF, 1'b0};
                        end else begin
                            z <= {1'b0, 8'hFF, 1'b1};
                        end
                    end else if (a_exponent == 8'hFF) begin
                        if (a[22:0] == 0) begin
                            if (b_exponent == 8'h00) begin
                                z <= {1'b0, 8'hFF, 1'b1};
                            end else begin
                                z_sign <= a_sign;
                                z <= {z_sign, 8'hFF, b_mantissa};
                            end
                        end else begin
                            z <= {1'b0, 8'hFF, 1'b1};
                        end
                    end else if (b_exponent == 8'hFF) begin
                        if (b[22:0] == 0) begin
                            z_sign <= b_sign;
                            z <= {z_sign, 8'hFF, a_mantissa};
                        end else begin
                            z <= {1'b0, 8'hFF, 1'b1};
                        end
                    end
                end else if (a_exponent == 8'h00 || b_exponent == 8'h00) begin
                    if (a_exponent == 8'h00) begin
                        if (a_mantissa == 0) begin
                            z_sign <= a_sign ^ b_sign;
                            if (b_exponent == 8'h00 && b_mantissa == 0) begin
                                z <= {1'b0, 8'hFF, 1'b1};
                            end else if (b_exponent == 8'hFF) begin
                                z <= {1'b0, 8'hFF, 1'b1};
                            end else begin
                                z <= {z_sign, 31'b0};
                            end
                        end else begin
                            if (b_exponent == 8'h00 && b_mantissa == 0) begin
                                z <= {1'b0, 8'hFF, 1'b1};
                            end else begin
                                z <= {z_sign, 31'b0};
                            end
                        end
                    end else begin
                        if (a_exponent == 8'hFF) begin
                            z <= {1'b0, 8'hFF, 1'b1};
                        end else begin
                            if (b_exponent == 8'h00 && b_mantissa == 0) begin
                                z <= {1'b0, 8'hFF, 1'b1};
                            end else begin
                                z <= {z_sign, 31'b0};
                            end
                        end
                    end
                end else begin
                    counter <= 2;
                end
            end
            2: begin

                a_mant <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                b_mant <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                sum_exponent <= a_exponent + b_exponent - 127;
                counter <= 3;
            end
            3: begin

                product <= a_mant * b_mant;
                counter <= 4;
            end
            4: begin

                if (product[47]) begin
                    product_shifted <= product >> 1;
                    sum_exponent <= sum_exponent + 1;
                end else begin
                    product_shifted <= product;
                end
                counter <= 5;
            end
            5: begin

                guard <= product_shifted[23 - (product[47] ? 0 : 1)];
                round <= product_shifted[22 - (product[47] ? 0 : 1)];
                sticky <= |(product_shifted[21:0] >> (product[47] ? 0 : 1));
                mantissa_rounded <= {1'b1, product_shifted[46:23]} << (product[47] ? 0 : 1);
                counter <= 6;
            end
            6: begin

                round_up <= guard & (round | sticky | (mantissa_rounded[0] & ~(round | sticky)));
                if (round_up) begin
                    mantissa_rounded <= mantissa_rounded + 1;
                end

                if (mantissa_rounded[24]) begin
                    mantissa_rounded <= mantissa_rounded >> 1;
                    sum_exponent <= sum_exponent + 1;
                end
                counter <= 7;
            end
            7: begin

                if (sum_exponent >= 255) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                end else if (sum_exponent <= 0) begin
                    z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                end else begin
                    z <= {a_sign ^ b_sign, sum_exponent[7:0], mantissa_rounded[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

