module fsm (
    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

    reg [2:0] current_state, next_state;


    localparam S0 = 3'b000,
               S1 = 3'b001,
               S2 = 3'b010,
               S3 = 3'b011,
               S4 = 3'b100;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            S0: begin
                next_state = IN ? S1 : S0;
            end
            S1: begin
                next_state = IN ? S1 : S2;
            end
            S2: begin
                next_state = IN ? S1 : S3;
            end
            S3: begin
                next_state = IN ? S4 : S0;
            end
            S4: begin
                next_state = IN ? S1 : S0;
            end
            default: next_state = S0;
        endcase
    end


    always @(*) begin
        if (RST) begin
            MATCH = 0;
        end else begin
            case (current_state)
                S4: MATCH = IN ? 1'b1 : 1'b0;
                default: MATCH = 1'b0;
            endcase
        end
    end

endmodule

