module LIFObuffer (
    input clk,
    input EN,
    input Rst,
    input RW,
    input [3:0] dataIn,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;



integer i;
always @(posedge clk) begin
    if (Rst) begin

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 0;
        SP <= 4;

        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 0;
    end else if (EN) begin
        if (!Rst) begin
            if (RW == 0) begin 
                if (SP != 4) begin
                    stack_mem[SP-1] <= dataIn;
                    SP <= SP - 1;

                    EMPTY <= (SP-1 == 4);
                    FULL <= (SP-1 == 0);
                end
            end else begin 
                if (SP != 4) begin
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 0;

                    SP <= SP + 1;

                    EMPTY <= (SP+1 == 4);
                    FULL <= (SP+1 == 0);
                end
            end
        end
    end

    EMPTY <= (SP == 4);
    FULL <= (SP == 0);
end

endmodule

