module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [1:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        counter <= 2'b11;
        valid_out <= 1'b0;
    end else begin
        if (counter == 2'b11) begin
            shift_reg <= d;
            counter <= 2'b0;
            valid_out <= 1'b1;
