module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= S0;
    end else begin
        case (state)
            S0: begin
                if (data_in == 0)
                    state <= S1;
                else
                    state <= S0;
            end
            S1: begin
                if (data_in == 1)
                    state <= S2;
                else
                    state <= S0;
            end
            S2: begin
                if (data_in == 0)
                    state <= S0;
                else
                    state <= S0;
            end
            default: state <= S0;
        endcase
    end
end


always @(*) begin
    data_out = (state == S2) && (data_in == 0);
end

endmodule

