module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
            cnt <= 10;
            clock <= 10;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                    cnt <= 60;
                    clock <= 60;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        red <= 0;
                        yellow <= 1;
                        green <= 0;
                        cnt <= 5;
                        clock <= 5;
                    end else begin
                        cnt <= cnt - 1;
                        clock <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        red <= 0;
                        yellow <= 0;
                        green <= 1;
                        cnt <= 10;
                        clock <= 10;
                    end else begin
                        cnt <= cnt - 1;
                        clock <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && (cnt > 10)) begin
                        cnt <= 10;
                        clock <= 10;
                    end else if (cnt == 0) begin
                        state <= s1_red;
                        red <= 1;
                        yellow <= 0;
                        green <= 0;
                        cnt <= 60;
                        clock <= 60;
                    end else begin
                        cnt <= cnt - 1;
                        clock <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end

