reg capture_next;
reg [15:0] combined_data;
reg valid_combined;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        upper_reg <= 0;
        capture_next <= 0;
        combined_data <= 0;
        valid_combined <= 0;
        valid_out <= 0;
        data_out <= 0;
    end else begin
        valid_out <= 0;


        if (capture_next) begin
            combined_data <= {upper_reg, data_in};
            valid_combined <= 1;
            capture_next <= 0;
        end


        if (valid_in) begin
            if (!capture_next) begin
                upper_reg <= data_in;
                capture_next <= 1;
                valid_combined <= 0;
            end
        end


        if (valid_combined) begin
            data_out <= combined_data;
            valid_out <= 1;
            valid_combined <= 0;
        end
    end
end

