module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    reg state;

    reg next_state;
    reg [4:0] next_wave;

    always @(*) begin
        next_state = state;
        next_wave = wave;

        case (state)
            0: begin
                next_wave = wave + 1;
                if (next_wave == 5'b11111)
                    next_state = 1;
            end
            1: begin
                next_wave = wave - 1;
                if (next_wave == 5'b00000)
                    next_state = 0;
            end
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 0;
            wave <= 0;
        end else begin
            state <= next_state;
            wave <= next_wave;
        end
    end

