module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] sum;
reg [32:0] diff;

always @(*) begin

    r = 32'bz;
    carry = 0;
    overflow = 0;
    flag = 1'bz;

    case (aluc)
        ADD: begin
            sum = {1'b0, a} + {1'b0, b};
            r = sum[31:0];
            carry = sum[32];
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            sum = {1'b0, a} + {1'b0, b};
            r = sum[31:0];
            carry = sum[32];
        end
        SUB: begin
            diff = {1'b0, a} - {1'b0, b};
            r = diff[31:0];
            carry = !diff[32];
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            diff = {1'b0, a} - {1'b0, b};
            r = diff[31:0];
            carry = !diff[32];
        end
        AND: begin
            r = a & b;
        end
        OR: begin
            r = a | b;
        end
        XOR: begin
            r = a ^ b;
        end
        NOR: begin
            r = ~(a | b);
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            flag = r[0];
        end
        SLTU: begin
            r = (a < b) ? 32'd1 : 32'd0;
            flag = r[0];
        end
        SLL: begin
            r = b << a[4:0];
        end
        SRL: begin
            r = b >> a[4:0];
        end
        SRA: begin
            r = $signed(b) >>> a[4:0];
        end
        SLLV: begin
            r = b << a[4:0];
        end
        SRLV: begin
            r = b >> a[4:0];
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
        end
        LUI: begin
            r = {b[15:0], 16'b0};
        end
        default: r = 32'bz;
    endcase

    negative = r[31];
end

assign zero = (r == 32'd0);

endmodule

