    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [3:0] cnt;
    reg start;
    reg [15:0] shift_reg;
    reg [7:0] divisor_abs;
    reg [7:0] absolute_dividend;
    reg [7:0] NEG_DIVISOR;
    reg sign_dividend;
    reg sign_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start <= 0;
            cnt <= 0;
            shift_reg <= 0;
            result <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            divisor_abs <= 0;
            absolute_dividend <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid && !start) begin

                sign_dividend <= dividend[7];
                sign_divisor <= divisor[7];
                if (sign) begin
                    absolute_dividend <= dividend[7] ? -dividend : dividend;
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                end else begin
                    absolute_dividend <= dividend;
                    divisor_abs <= divisor;
