                NEG_DIVISOR <= -divisor_abs;
                shift_reg <= {absolute_dividend, 8'b0};
                cnt <= 4'd1;
                start <= 1;
                res_valid <= 0;
            end else if (start) begin
                if (cnt < 4'd8) begin

                    shift_reg <= {shift_reg[14:0], 1'b0};
