                        shift_reg[15:8] <= shift_reg[15:8] - divisor_abs;
                        shift_reg[0] <= 1'b1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    start <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        if (sign_dividend ^ sign_divisor) begin
                            shift_reg[7:0] <= -shift_reg[7:0];
                        end
                        if (sign_dividend) begin
                            shift_reg[15:8] <= -shift_reg[15:8];
                        end
                    end
                    result <= {shift_reg[15:8], shift_reg[7:0]};
                end
            end
        end
