module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

always @(*) begin
    reg [15:0] quotient = 0;
    reg [15:0] remainder;
    integer i;


    remainder = A[15:8];
    for (i = 0;
 i < 8;
 i = i + 1) begin

        remainder = {remainder[6:0], A[7 - i]};
        if (remainder >= {8'b0, B}) begin
            quotient[15 - i] = 1'b1;
            remainder = remainder - {8'b0, B};
        end else begin
            quotient[15 - i] = 1'b0;
        end
    end


    for (i = 0;
 i < 8;
 i = i + 1) begin
        remainder = {remainder[6:0], A[7 - i]};
        if (remainder >= {8'b0, B}) begin
            quotient[7 - i] = 1'b1;
            remainder = remainder - {8'b0, B};
        end else begin
            quotient[7 - i] = 1'b0;
        end
    end

    result = quotient;
    odd = {8'b0, remainder};
end

endmodule

