module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] sum;

    always @(*) begin

        a_abs = a[N-1] ? (~a + 1) : a;
        b_abs = b[N-1] ? (~b + 1) : b;

        if (a[N-1] == b[N-1]) begin

            sum = a_abs + b_abs;
            c = {sum[N-1], sum[N-2:0]};
        end else begin

            if (a_abs > b_abs) begin
                sum = a_abs - b_abs;
                c = {1'b0, sum[N-2:0]};
            end else if (b_abs > a_abs) begin
                sum = b_abs - a_abs;
                c = {1'b1, sum[N-2:0]};
            end else begin

                c = {1'b0, {N-Q-1{1'b0}}};
            end
        end
    end

endmodule

