module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            c = a - b;
        end else begin

            if (a[N-1] == 0) begin

                c = a + (~b + 1);
            end else begin

                c = (~a + 1) - b;
            end
        end


        if (c == 0) begin
            c[N-1] = 0;
        end
    end

endmodule

