module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, product_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 1;
                end

                1: begin

                    if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                        if (a_exponent == 8'hFF && b_exponent == 8'hFF) begin

                            z <= {1'b0, 8'hFF, 23'h1};
                        end else if (a_exponent == 8'hFF) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        counter <= 0;
                    end else if (a_mantissa == 0 && b_mantissa == 0) begin

                        z <= 0;
                        counter <= 0;
                    end else if (a_exponent == 0 && a_mantissa == 0 && b_mantissa != 0) begin

                        z <= 0;
                        counter <= 0;
                    end else if (a_mantissa != 0 && b_exponent == 0 && b_mantissa == 0) begin

                        z <= 0;
                        counter <= 0;
                    end else begin
                        product <= a_mantissa * b_mantissa;
                        product_mantissa <= product[46:24];

                        counter <= 2;
                    end
                end

                2: begin

                    if (product[47]) begin
                        product_mantissa <= product[46:24];
                        z_exponent <= a_exponent + b_exponent + 1;
                    end else begin
                        product_mantissa <= product[45:23];
                        z_exponent <= a_exponent + b_exponent;
                    end

                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];
                    if (guard && (round || sticky)) begin
                        product_mantissa <= product_mantissa + 1;
                    end
                    counter <= 3;
                end

                3: begin

                    if (product_mantissa[23]) begin
                        product_mantissa <= product_mantissa >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    if (z_exponent > 254) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else if (z_exponent == 0) begin

                        z <= {a_sign ^ b_sign, 0, product_mantissa[22:0]};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], product_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

