    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

    wire [7:0] stage1 = ctrl[2] ? {in[3:0], in[7:4]} : in;
    wire [7:0] stage2 = ctrl[1] ? {stage1[1:0], stage1[7:2]} : stage1;
    wire [7:0] stage3 = ctrl[0] ? {stage2[0], stage2[7:1]} : stage2;

    assign out = stage3;

endmodule

