module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] mem [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc) begin
        mem[waddr] <= wdata;
    end
end

always @(posedge rclk) begin
    if (renc) begin
        rdata <= mem[raddr];
    end
end

endmodule

module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);

localparam PTR_WIDTH = $clog2(DEPTH) + 1;

localparam ADDR_WIDTH = $clog2(DEPTH);


reg [PTR_WIDTH-1:0] wptr_bin = 0, rptr_bin = 0;
wire [ADDR_WIDTH-1:0] waddr_bin = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr_bin = rptr_bin[ADDR_WIDTH-1:0];


wire [PTR_WIDTH-1:0] wptr_gray = wptr_bin ^ (wptr_bin >> 1);
wire [PTR_WIDTH-1:0] rptr_gray = rptr_bin ^ (rptr_bin >> 1);


reg [PTR_WIDTH-1:0] wptr_gray_sync_rclk [1:0];
reg [PTR_WIDTH-1:0] rptr_gray_sync_wclk [1:0];


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_gray_sync_rclk <= {PTR_WIDTH{0}};
    end else begin
        wptr_gray_sync_rclk[0] <= rptr_gray;
        wptr_gray_sync_rclk[1] <= wptr_gray_sync_rclk[0];
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_gray_sync_wclk <= {PTR_WIDTH{0}};
    end else begin
        rptr_gray_sync_wclk[0] <= wptr_gray;
        rptr_gray_sync_wclk[1] <= rptr_gray_sync_wclk[0];
    end
end


wire [PTR_WIDTH-1:0] wptr_gray_sync = wptr_gray_sync_rclk[1];
wire [PTR_WIDTH-1:0] rptr_gray_sync = rptr_gray_sync_wclk[1];

wire full = (wptr_gray[ADDR_WIDTH] ^ wptr_gray_sync[ADDR_WIDTH]) &&
            (wptr_gray[ADDR_WIDTH-1] ^ wptr_gray_sync[ADDR_WIDTH-1]) &&
            (wptr_gray[ADDR_WIDTH-2:0] == wptr_gray_sync[ADDR_WIDTH-2:0]);

wire empty = (rptr_gray == rptr_gray_sync);

assign wfull = full;
assign rempty = empty;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else if (winc && !full) begin
        wptr_bin <= wptr_bin + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else if (rinc && !empty) begin
        rptr_bin <= rptr_bin + 1;
    end
end


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram_inst (
    .wclk(wclk),
    .wenc(winc && !full),
    .waddr(waddr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !empty),
    .raddr(raddr_bin),
    .rdata(rdata)
);

endmodule

