module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 4;
        for (integer i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 0;
        end
        dataOut <= 0;

    end
    else if (EN) begin
        if (!RW) begin 
            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;

                SP <= SP - 1;

            end
        end
        else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP-1];

                SP <= SP + 1;

            end
        end
    end
end


always @(*) begin
    EMPTY = (SP == 4);
    FULL = (SP == 0);
end

endmodule

