module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [3:0] state;
reg [7:0] dividend_reg, divisor_reg;
reg [7:0] abs_dividend, abs_divisor;
reg [7:0] quotient_abs, remainder_abs;
reg sign_quot, sign_rem;
reg [16:0] shift_reg;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] neg_div;

localparam IDLE = 0;
localparam CAPTURE = 1;
localparam DIV = 2;
localparam ADJUST = 3;
localparam DONE = 4;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        shift_reg <= 0;
        sign_quot <= 0;
        sign_rem <= 0;
        quotient_abs <= 0;
        remainder_abs <= 0;
        neg_div <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin
                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                    if (sign) begin
                        abs_dividend <= dividend[7] ? -dividend : dividend;
                        abs_divisor <= divisor[7] ? -divisor : divisor;
                        sign_quot <= dividend[7] ^ divisor[7];
                        sign_rem <= dividend[7];
                        neg_div <= ~(divisor[7] ? -divisor : divisor);
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                        sign_quot <= 0;
                        sign_rem <= 0;
                        neg_div <= ~(divisor);
                    end
                    shift_reg <= {abs_dividend << 1, 8'b0};
                    cnt <= 1;
                    start_cnt <= 1;
                    state <= DIV;
                end
            end

            DIV: begin
                if (cnt == 8) begin
                    quotient_abs <= shift_reg[7:0];
                    remainder_abs <= shift_reg[16:9];
                    state <= ADJUST;
                end else begin
                    if (shift_reg[16:9] >= abs_divisor) begin
                        shift_reg <= {shift_reg[16:9] - abs_divisor, 1'b1, shift_reg[8:0], 1'b0};
                    end else begin
                        shift_reg <= {shift_reg[16:9], 1'b0, shift_reg[8:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end

            ADJUST: begin
                if (sign) begin
                    remainder_abs <= sign_rem ? -remainder_abs : remainder_abs;
                    quotient_abs <= sign_quot ? -quotient_abs : quotient_abs;
                end
                state <= DONE;
            end

            DONE: begin
                result <= {remainder_abs, quotient_abs};
                res_valid <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

