module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [7:0] a_reg;
    reg [7:0] b_reg;


    always @(*) begin
        a_reg = A[15:8];

        b_reg = B;

    end


    always @(*) begin
        reg [7:0] remainder;
        reg [15:0] quotient;
        reg [7:0] temp;
        integer i;

        remainder = a_reg;
        quotient = 0;

        for (i = 0;
 i < 16;
 i = i + 1) begin

            temp = remainder << 1;
            temp[0] = (A >> (15 - i)) & 1;


            if (temp >= b_reg) begin
                remainder = temp - b_reg;
                quotient = (quotient << 1) | 1;
            end else begin
                remainder = temp;
                quotient = quotient << 1;
            end
        end


        result = quotient;
        odd = {8'b0, remainder};

    end

endmodule

