module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out = 0,
    output [9:0] data_out
);

reg [9:0] sum_reg;
reg [1:0] count;
reg [1:0] count_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 0;
        count <= 0;
        count_prev <= 0;
        valid_out <= 0;
    end else begin
        valid_out <= 0;
        count_prev <= count;

        if (valid_in) begin
            sum_reg <= sum_reg + data_in;
            if (count == 2'b11)
                count <= 0;
            else
                count <= count + 1;
        end else
            count <= count;

        if (count_prev == 2'b11 && count == 0)
            valid_out <= 1;
    end
end

assign data_out = sum_reg;

endmodule

