module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] mag_a, mag_b;
    reg [N-1:0] res_mag;
    reg res_sign;

    always @(*) begin

        mag_a = a[N-1] ? (~a + 1) : a;
        mag_b = b[N-1] ? (~b + 1) : b;


        if (a[N-1] == b[N-1]) begin

            res_mag = mag_a + mag_b;
            res_sign = a[N-1];
        end else begin

            if (mag_a > mag_b) begin
                res_mag = mag_a - mag_b;
                res_sign = a[N-1];
            end else if (mag_b > mag_a) begin
                res_mag = mag_b - mag_a;
                res_sign = b[N-1];
            end else begin

                res_mag = {N{1'b0}};
                res_sign = 1'b0;
            end
        end


        c = {res_sign, res_mag[N-1:1]};

    end

endmodule

