module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 32'd0
);

    reg [2:0] counter = 0;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;

    localparam INIT = 3'd0;
    localparam PROCESS = 3'd1;
    localparam SPECIAL_CASES = 3'd2;
    localparam NORMALIZE = 3'd3;
    localparam ROUND = 3'd4;
    localparam ADJUST = 3'd5;
    localparam FINISH = 3'd6;

    always @(posedge clk) begin
        if (rst) begin
            counter <= INIT;
            z <= 32'd0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            z_mantissa <= 0;
            z_exponent <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                INIT: begin
                    counter <= PROCESS;
                end
                PROCESS: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= (a[30:23] == 8'd0) ? 9'd1 : {1'b0, a[30:23]};
                    b_exponent <= (b[30:23] == 8'd0) ? 9'd1 : {1'b0, b[30:23]};
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= SPECIAL_CASES;
                end
                SPECIAL_CASES: begin

                    if (a_exponent == 9'h1ff && a_mantissa != 0) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= INIT;
                    end else if (b_exponent == 9'h1ff && b_mantissa != 0) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= INIT;
                    end else if (a_exponent == 9'h1ff && a_mantissa == 0 &&
                               b_exponent == 9'h1ff && b_mantissa == 0) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        counter <= INIT;
                    end else if (a_exponent == 9'h1ff && a_mantissa == 0) begin
                        z <= (b_exponent == 9'h1ff) ? {a_sign ^ b_sign, 8'hff, 23'h0} : 32'd0;
                        counter <= INIT;
                    end else if (b_exponent == 9'h1ff && b_mantissa == 0) begin
                        z <= (a_exponent == 9'h1ff) ? {a_sign ^ b_sign, 8'hff, 23'h0} : 32'd0;
                        counter <= INIT;
                    end else if (a_exponent == 0 && a_mantissa == 0 && b_exponent == 0 && b_mantissa == 0) begin
                        z <= 32'd0;
                        counter <= INIT;
                    end else begin
                        counter <= NORMALIZE;
                    end
                end
                NORMALIZE: begin
                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 9'h0ff;
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= ROUND;
                end
                ROUND: begin
                    guard <= product[23];
                    round <= product[22];
                    sticky <= |product[21:0];
                    counter <= ADJUST;
                end
                ADJUST: begin
                    if ((guard & (round | sticky)) || (guard && !round && !sticky)) begin
                        if (z_mantissa[0]) begin
                            z_mantissa <= {1'b1, z_mantissa[23:1]};
                            if (z_exponent == 0) begin

                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                                counter <= INIT;
                            end else begin
                                z_exponent <= z_exponent - 1;
                            end
                        end else begin
                            z_mantissa <= {1'b1, z_mantissa[23:1]};
                        end
                    end else begin
                        z_mantissa <= {1'b1, z_mantissa[23:1]};
                    end
                    counter <= FINISH;
                end
                FINISH: begin

                    if (z_exponent > 9'h0ff) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (z_exponent < 9'd1) begin

                        z <= {a_sign ^ b_sign, 8'd0, 23'd0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= INIT;
                end
                default: counter <= INIT;
            endcase
        end
    end

endmodule

