        	    		a_exponent <= -126;
        	  	else
        	    		a_mantissa[23] <= 1;

        	    	if ($signed(b_exponent) == -127) //DENORMALIZING B
        	    		b_exponent <= -126;
        	  	else
        	    		b_mantissa[23] <= 1;
        	  end
