module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);

reg [2:0] state;
localparam S0 = 3'b000,
           S1 = 3'b001,
           S2 = 3'b010,
           S3 = 3'b011,
           S4 = 3'b100;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
    end else begin
        case (state)
            S0: state <= IN ? S1 : S0;
            S1: state <= IN ? S1 : S2;
            S2: state <= IN ? S1 : S3;
            S3: state <= IN ? S1 : S4;
            S4: state <= IN ? S1 : S0;
            default: state <= S0;
        endcase
    end
end

assign MATCH = RST ? 1'b0 : ((state == S4) && IN);

endmodule

