module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'b100;
        EMPTY <= 1;
        FULL <= 0;
        for (integer i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 0;
    end else if (EN) begin
        if (RW) begin 
            if (!FULL) begin
                dataOut <= stack_mem[SP];
                SP <= SP + 1;
                FULL <= (SP + 1 == 3'b100) ? 1 : 0;
                EMPTY <= (SP + 1 == 3'b100) ? 0 : (SP == 3'b100);
            end
        end else begin 
            if (!FULL) begin
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
                FULL <= (SP - 1 == 0) ? 1 : 0;
                EMPTY <= (SP - 1 == 0) ? 0 : EMPTY;
            end
        end
    end

    EMPTY <= (SP == 3'b100);
    FULL <= (SP == 0);
end

endmodule

