module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


localparam IDLE     = 2'b00;
localparam S1_RED   = 2'b01;
localparam S2_YELLOW = 2'b10;
localparam S3_GREEN = 2'b11;

reg [1:0] state;
reg [7:0] cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        cnt <= 8'd10;
    end else begin
        case (state)
            IDLE: begin
                state <= S1_RED;
                cnt <= 8'd10;
            end
            S1_RED: begin
                if (cnt == 0) begin
                    state <= S3_GREEN;
                    cnt <= 8'd60;
                end else begin
                    cnt <= cnt - 1;
                end
            end
            S3_GREEN: begin
                if (pass_request) begin
                    if (cnt > 8'd10)
                        cnt <= 8'd10;
                end
                if (cnt == 0) begin
                    state <= S2_YELLOW;
                    cnt <= 8'd5;
                end else begin
                    cnt <= cnt - 1;
                end
            end
            S2_YELLOW: begin
                if (cnt == 0) begin
                    state <= S1_RED;
                    cnt <= 8'd10;
                end else begin
                    cnt <= cnt - 1;
                end
            end
            default: state <= IDLE;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {red, yellow, green} <= 3'b000;
    end else begin
        case (state)
            IDLE:     {red, yellow, green} <= 3'b000;
            S1_RED:   {red, yellow, green} <= 3'b100;
            S3_GREEN: {red, yellow, green} <= 3'b001;
            S2_YELLOW:{red, yellow, green} <= 3'b010;
            default:  {red, yellow, green} <= 3'b000;
        endcase
    end
end

assign clock = cnt;

endmodule

