module alu (
  input [31:0] a,
  input [31:0] b,
  input [5:0] aluc,
  output reg [31:0] r,
  output zero,
  output reg carry,
  output negative,
  output reg overflow,
  output flag
);

  parameter ADD  = 6'b100000;
  parameter ADDU = 6'b100001;
  parameter SUB  = 6'b100010;
  parameter SUBU = 6'b100011;
  parameter AND  = 6'b100100;
  parameter OR   = 6'b100101;
  parameter XOR  = 6'b100110;
  parameter NOR  = 6'b100111;
  parameter SLT  = 6'b101010;
  parameter SLTU = 6'b101011;
  parameter SLL  = 6'b000000;
  parameter SRL  = 6'b000010;
  parameter SRA  = 6'b000011;
  parameter SLLV = 6'b000100;
  parameter SRLV = 6'b000110;
  parameter SRAV = 6'b000111;
  parameter LUI  = 6'b001111;

  wire [32:0] sum_33 = {1'b0, a} + {1'b0, b};
  wire [32:0] diff_33 = {1'b0, a} - {1'b0, b};

  always @(*) begin
    case (aluc)
      ADD:  r = sum_33[31:0];
      ADDU: r = sum_33[31:0];
      SUB:  r = diff_33[31:0];
      SUBU: r = diff_33[31:0];
      AND:  r = a & b;
      OR:   r = a | b;
      XOR:  r = a ^ b;
      NOR:  r = ~(a | b);
      SLT:  r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
      SLTU: r = (a < b) ? 32'd1 : 32'd0;
      SLL:  r = a << b[4:0];
      SRL:  r = a >> b[4:0];
      SRA:  r = $signed(a) >>> b[4:0];
      SLLV: r = a << a[4:0];
      SRLV: r = a >> a[4:0];
      SRAV: r = $signed(a) >>> a[4:0];
      LUI:  r = {a[15:0], 16'b0};
      default: r = 32'bz;
    endcase
  end

  assign zero = (r == 32'b0);
  assign negative = r[31];

  always @(*) begin
    case (aluc)
      ADD: begin
        overflow = (a[31] == b[31]) && (r[31] != a[31]);
        carry = sum_33[32];
      end
      ADDU: begin
        carry = sum_33[32];
        overflow = 0;
      end
      SUB: begin
        overflow = (a[31] != b[31]) && (r[31] != a[31]);
        carry = diff_33[32];
      end
      SUBU: begin
        carry = diff_33[32];
        overflow = 0;
      end
      default: begin
        carry = 0;
        overflow = 0;
      end
    endcase
  end

  assign flag = (aluc == SLT) ? ( ($signed(a) < $signed(b)) ? 1 : 0 ) :
                (aluc == SLTU) ? ( (a < b) ? 1 : 0 ) : 1'bz;

endmodule

