module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] div_reg;
    reg [7:0] divisor_abs;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [3:0] cnt;
    reg processing;
    reg sign_quotient;
    reg sign_remainder;
    reg [7:0] neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            remainder <= 0;
            quotient <= 0;
            div_reg <= 0;
            neg_divisor <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
        end else begin
            if (!processing && !res_valid && opn_valid) begin

                if (sign) begin
                    div_reg <= dividend[7] ? -dividend : dividend;
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                    sign_quotient <= (dividend[7] == divisor[7]);
                    sign_remainder <= dividend[7];
                end else begin
                    div_reg <= dividend;
                    divisor_abs <= divisor;
                    sign_quotient <= 1;
                    sign_remainder <= 0;
                end
                remainder <= 0;
                quotient <= 0;
                neg_divisor <= ~divisor_abs + 1;
                cnt <= 1;
                processing <= 1;
            end else if (processing) begin
                if (cnt == 8) begin

                    if (sign) begin
                        if (!sign_quotient)
                            quotient <= -quotient;
                        if (sign_remainder)
                            remainder <= divisor_abs - remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    processing <= 0;
                    cnt <= 0;
                end else begin

                    if (remainder[8]) begin 
