module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    integer i;
    reg [8:0] temp_remainder;
    reg [7:0] remainder;
    reg [15:0] quotient;

    remainder = 8'b0;
    quotient = 16'b0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        temp_remainder = (remainder << 1) | ((a_reg >> i) & 1);

        if (temp_remainder >= {1'b0, b_reg}) begin
            remainder = temp_remainder - {1'b0, b_reg};
            quotient[i] = 1;
        end else begin
            remainder = temp_remainder;
            quotient[i] = 0;
        end
    end

    result = quotient;
    odd = {8'b0, remainder};
end

endmodule

