module fixed_point_adder #(
    parameter Q = 2, 
    parameter N = 4  
)(
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);


    reg [N-1:0] res;

    always @(*) begin

        reg a_sign = a[N-1];
        reg b_sign = b[N-1];
        reg [N-2:0] a_mag = a[N-2:0];
        reg [N-2:0] b_mag = b[N-2:0];
        reg [N-1:0] result;

        if (a_sign == b_sign) begin

            result = {a_sign, (a_mag + b_mag)};
        end else begin

            if (a_mag > b_mag) begin
                result = {a_sign, (a_mag - b_mag)};
            end else if (b_mag > a_mag) begin
                result = {b_sign, (b_mag - a_mag)};
            end else begin

                result = 0;
            end
        end


        if (result[N-2:0] > (N-2>'0 ? {N-2{1'b1}} : 0)) begin
            result[N-2:0] = {N-2{1'b1}};

        end

        res = result;
    end

    assign c = res;

endmodule

