    end else begin

        reg [N-1:0] magnitude_a = a[N-1] ? (~a + 1) : a;
        reg [N-1:0] magnitude_b = b[N-1] ? (~b + 1) : b;
        reg [N-1:0] diff;
        if (magnitude_a > magnitude_b) begin
            diff = magnitude_a - magnitude_b;
            c = {1'b0, diff[N-2:0]};
        end else if (magnitude_b > magnitude_a) begin
            diff = magnitude_b - magnitude_a;
            c = {1'b1, diff[N-2:0]};
        end else begin

            c = 0;
        end
    end
end

