module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;

reg [47:0] product;
reg guard, round, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};

                if (a[30:23] == 8'hFF || b[30:23] == 8'hFF) begin

                    if ((a[30:23] == 8'hFF && a[22:0] != 0) || (b[30:23] == 8'hFF && b[22:0] != 0)) begin
                        z <= {1'b0, 8'hFF, 23'h1};
                    end else if ((a[30:23] == 8'hFF && a[22:0] == 0) && (b[30:23] == 8'hFF && b[22:0] == 0)) begin
                        z <= {a[31] ^ b[31], 8'hFF, 23'h0};
                    end else if (a[30:23] == 8'hFF && a[22:0] == 0) begin
                        if (b[30:23] == 8'hFF && b[22:0] == 0) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin
                            z <= {a[31] ^ b[31], 8'hFF, 23'h0};
                        end
                    end else if (b[30:23] == 8'hFF && b[22:0] == 0) begin
                        if (a[30:23] == 8'hFF && a[22:0] == 0) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin
                            z <= {a[31] ^ b[31], 8'hFF, 23'h0};
                        end
                    end
                end else if ((a[30:23] == 0 && a[22:0] == 0) || (b[30:23] == 0 && b[22:0] == 0)) begin

                    if (a[30:23] == 0 && a[22:0] == 0) begin
                        if (b[30:23] == 8'hFF || (b[30:23] == 0 && b[22:0] == 0)) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin
                            z <= {a[31] ^ b[31], 8'h0, 23'h0};
                        end
                    end else begin
                        if (a[30:23] == 8'hFF || (a[30:23] == 0 && a[22:0] == 0)) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else begin
                            z <= {a[31] ^ b[31], 8'h0, 23'h0};
                        end
                    end
                end else begin
                    counter <= 1;
                end
            end
            1: begin

                product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                counter <= 2;
            end
            2: begin

                guard <= product[22];
                round <= product[21];
                sticky <= |product[20:0];
                if (product[47]) begin
                    product <= product >> 1;
                    z_exponent <= a_exponent + b_exponent - 8'd126 + 1;
                end else begin
                    z_exponent <= a_exponent + b_exponent - 8'd126;
                end
                counter <= 3;
            end
            3: begin

                if (guard && (round || sticky)) begin
                    product <= product + 1;

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                end
                counter <= 4;
            end
            4: begin

                if (z_exponent >= 8'hFF) begin
                    z <= {z_sign, 8'hFF, 23'h0};
                end else if (z_exponent <= 0) begin
                    z <= {z_sign, 8'h0, 23'h0};
                end else begin
                    z <= {z_sign, z_exponent, product[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

