module LIFObuffer (
    input Clk,
    input EN,
    input Rst,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


assign EMPTY = (SP == 3'b100);

assign FULL = (SP == 3'b000);


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'b100;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
    end
    else if (EN) begin
        if (!FULL && !EMPTY) begin
            if (RW == 0) begin 
                stack_mem[SP[1:0]] <= dataIn;
                SP <= SP - 1;
            end
            else begin 
                dataOut <= stack_mem[SP[1:0]];
                SP <= SP + 1;
            end
        end
        else if (RW == 0 && !FULL) begin 
            stack_mem[SP[1:0]] <= dataIn;
            SP <= SP - 1;
        end
        else if (RW && !EMPTY) begin 
            dataOut <= stack_mem[SP[1:0]];
            SP <= SP + 1;
        end
    end
end

endmodule

