module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg [32:0] temp_add, temp_sub;
    reg [31:0] temp_shift;
    reg [31:0] slt_res, sltu_res;
    reg flag_val;


    assign zero = (res == 32'b0);
    assign negative = res[31];


    assign flag = ((aluc == SLT) || (aluc == SLTU)) ? flag_val : 1'bz;

    always @(*) begin
        temp_add = {1'b0, a} + {1'b0, b};
        temp_sub = {1'b0, a} - {1'b0, b};
        slt_res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        sltu_res = (a < b) ? 32'd1 : 32'd0;
        flag_val = (aluc == SLT) ? slt_res[0] : sltu_res[0];


        case (aluc)
            ADD: begin
                res = temp_add[31:0];
                carry = temp_add[32];
                overflow = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
            end
            ADDU: begin
                res = temp_add[31:0];
                carry = temp_add[32];
                overflow = 0;

            end
            SUB: begin
                res = temp_sub[31:0];
                carry = ~temp_sub[32];

                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = temp_sub[31:0];
                carry = ~temp_sub[32];

                overflow = 0;

            end
            AND: begin
                res = a & b;
                carry = 0;
                overflow = 0;
            end
            OR: begin
                res = a | b;
                carry = 0;
                overflow = 0;
            end
            XOR: begin
                res = a ^ b;
                carry = 0;
                overflow = 0;
            end
            NOR: begin
                res = ~(a | b);
                carry = 0;
                overflow = 0;
            end
            SLT: begin
                res = slt_res;
                carry = 0;
                overflow = 0;
            end
            SLTU: begin
                res = sltu_res;
                carry = 0;
                overflow = 0;
            end
            SLL: begin
                res = b << a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                carry = 0;
                overflow = 0;
            end
            SLLV: begin
                res = a << b[4:0];
                carry = 0;
                overflow = 0;
            end
            SRLV: begin
                res = a >> b[4:0];
                carry = 0;
                overflow = 0;
            end
            SRAV: begin
                res = $signed(a) >>> b[4:0];
                carry = 0;
                overflow = 0;
            end
            LUI: begin
                res = {b[15:0], 16'b0};


                res = {a[15:0], 16'b0};
                carry = 0;
                overflow = 0;
            end
            default: begin
                res = 32'bz;
                carry = 0;
                overflow = 0;
            end
        endcase
    end

    assign r = res;

endmodule

