module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg quotient_sign;
reg remainder_sign;
reg [3:0] cnt;
reg [15:0] shift_reg;

reg [7:0] NEG_DIVISOR;
reg state;


localparam IDLE = 0;
localparam PROCESSING = 1;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        shift_reg <= 0;
        cnt <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        dividend_abs <= dividend[7] ? -dividend : dividend;
                        divisor_abs <= divisor[7] ? -divisor : divisor;
                        quotient_sign <= (dividend[7] ^ divisor[7]);
                        remainder_sign <= dividend[7];
                    end else begin
                        dividend_abs <= dividend;
                        divisor_abs <= divisor;
                        quotient_sign <= 0;
                        remainder_sign <= 0;
                    end
                    NEG_DIVISOR <= -divisor_abs;

                    shift_reg <= { {8{dividend_abs[7]}}, dividend_abs } << 1;

                    cnt <= 0;
                    state <= PROCESSING;
                end
            end
            PROCESSING: begin
                if (cnt < 8) begin

                    if (shift_reg[15:8] >= NEG_DIVISOR) begin
                        shift_reg <= { (shift_reg[15:8] - NEG_DIVISOR), shift_reg[7:0], 1'b1 } << 1;
                    end else begin
                        shift_reg <= { shift_reg[15:8], shift_reg[7:0], 1'b0 } << 1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    result <= { shift_reg[15:8], shift_reg[7:0] };
                    res_valid <= 1;
                    state <= IDLE;
                    if (sign) begin

                        if (quotient_sign) result[7:0] <= -result[7:0];
                        if (remainder_sign) result[15:8] <= -result[15:8];
                    end
                end
            end
        endcase
    end
end

endmodule

