module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [7:0] a_reg, b_reg;

always @(*) begin
    a_reg = A[15:8];

    b_reg = B;

end

always @(*) begin
    reg [8:0] temp_remainder;

    reg [15:0] temp_result;
    integer i;

    temp_remainder = {a_reg, 1'b0};

    temp_result = 0;

    for (i = 0;
 i < 16;
 i = i + 1) begin

        temp_remainder = (temp_remainder << 1) | ((A >> (15 - i)) & 1);

        if (temp_remainder >= {1'b0, b_reg}) begin
            temp_remainder = temp_remainder - {1'b0, b_reg};
            temp_result = {1'b1, temp_result[14:0]};

        end else begin
            temp_result = {1'b0, temp_result[14:0]};
        end
    end


    odd = {7'b0, temp_remainder[7:0]};
    result = temp_result;
end

endmodule

