    assign C[0] = C0;


    assign G_bits[1] = A[1] & B[1];
    assign P_bits[1] = A[1] ^ B[1];
    assign C[1] = G_bits[1] | (P_bits[1] & C[0]);


    assign G_bits[2] = A[2] & B[2];
    assign P_bits[2] = A[2] ^ B[2];
    assign C[2] = G_bits[2] | (P_bits[2] & C[1]);


    assign G_bits[3] = A[3] & B[3];
