    assign C[3] = G_bits[3] | (P_bits[3] & C[2]);


    assign G_bits[4] = A[4] & B[4];
    assign P_bits[4] = A[4] ^ B[4];
    assign C[4] = G_bits[4] | (P_bits[4] & C[3]);


    assign G = C[4];
    assign P = &P_bits;


    assign S[1] = P_bits[1] ^ C[0];
    assign S[2] = P_bits[2] ^ C[1];
    assign S[3] = P_bits[3] ^ C[2];
