module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-2:0] abs_mag_a, abs_mag_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] res;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];


        abs_mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
        abs_mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];


        abs_a = {1'b0, abs_mag_a};
        abs_b = {1'b0, abs_mag_b};

        if (sign_a == sign_b) begin

            res = a + b;
        end else begin

            if (abs_a > abs_b) begin
                res = {sign_a, (abs_a - abs_b)[N-2:0]};
            end else if (abs_b > abs_a) begin
                res = {sign_b, (abs_b - abs_a)[N-2:0]};
            end else begin

                res = 0;
            end
        end
    end

    assign c = res;

endmodule

