module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);
    reg [2:0] counter;
    reg [23:0] a_mant, b_mant, z_mant;
    reg [8:0] a_exp, b_exp, z_exp;

    reg a_sign, b_sign, z_sign;
    reg [47:0] product;
    reg guard, round, sticky;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)

                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= {1'b0, a[30:23]};
                    b_exp <= {1'b0, b[30:23]};
                    a_mant <= {1'b1, a[22:0]};
                    b_mant <= {1'b1, b[22:0]};
                    counter <= 1;
                end


                1: begin
                    if (a_exp == 9'h1FF || b_exp == 9'h1FF) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (a_exp == 0 && b_exp == 0) begin

                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin
                        z_exp <= a_exp + b_exp - 9'd127;
                        product <= {1'b0, a_mant} * {1'b0, b_mant};
                        counter <= 2;
                    end
                end


                2: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exp <= z_exp + 1;
                    end
                    z_mant <= product[46:24];
                    counter <= 3;
                end


                3: begin
                    guard <= product[23];
                    round <= product[22];
                    sticky <= |product[21:0];
                    if (guard) begin
                        if (round || sticky)
                            z_mant <= z_mant + 1;
                        else if (z_mant[0])
                            z_mant <= z_mant + 1;
                    end
                    if (z_mant == 24'h1000000) begin
                        z_mant <= 24'h0;
                        z_exp <= z_exp + 1;
                    end
                    counter <= 4;
                end


                4: begin
                    overflow <= z_exp[8];
                    underflow <= (z_exp < 9'h1);
                    if (overflow)
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    else if (underflow)
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    else
                        z <= {a_sign ^ b_sign, z_exp[7:0], z_mant[22:0]};
                    counter <= 0;
                end
