        end
        S3: begin
            if (IN) next_state = S4;
            else next_state = S2;
        end
        S4: begin
            if (IN) begin
                next_state = S1;
                MATCH = 1'b1;
            end else begin
                next_state = S2;
            end
        end
        default: next_state = S0;
    endcase
end

