module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,

    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;

    reg [PTR_WIDTH-1:0] waddr_bin = 0;
    reg [PTR_WIDTH-1:0] raddr_bin = 0;

    wire [PTR_WIDTH-1:0] wgray = (waddr_bin >> 1) ^ waddr_bin;
    wire [PTR_WIDTH-1:0] rgray = (raddr_bin >> 1) ^ raddr_bin;

    reg [PTR_WIDTH-1:0] wgray_sync_rd [1:0];
    reg [PTR_WIDTH-1:0] rgray_sync_wr [1:0];


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rgray_sync_wr[0] <= 0;
            rgray_sync_wr[1] <= 0;
        end else begin
            rgray_sync_wr[0] <= rgray;
            rgray_sync_wr[1] <= rgray_sync_wr[0];
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wgray_sync_rd[0] <= 0;
            wgray_sync_rd[1] <= 0;
        end else begin
            wgray_sync_rd[0] <= wgray;
            wgray_sync_rd[1] <= wgray_sync_rd[0];
        end
    end


    wire full_condition = (wgray[PTR_WIDTH-1] != rgray_sync_wr[1][PTR_WIDTH-1]) &&
                          (wgray[PTR_WIDTH-2] != rgray_sync_wr[1][PTR_WIDTH-2]) &&
                          (wgray[PTR_WIDTH-3:0] == rgray_sync_wr[1][PTR_WIDTH-3:0]);


    wire empty_condition = (rgray == wgray_sync_rd[1]);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else begin
            if (winc && !full_condition) begin
                waddr_bin <= waddr_bin + 1;
            end
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else begin
            if (rinc && !empty_condition) begin
                raddr_bin <= raddr_bin + 1;
            end
        end
    end


    reg wfull_reg;
    reg rempty_reg;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull_reg <= 0;
        end else begin
            wfull_reg <= full_condition;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty_reg <= 1;
        end else begin
            rempty_reg <= empty_condition;
        end
    end

    assign wfull = wfull_reg;
    assign rempty = rempty_reg;


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !rempty_reg),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !wfull_reg),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );

endmodule


