module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;


    assign EMPTY = (SP == 0);
    assign FULL = (SP == 4);
    assign dataOut = (RW && !EMPTY) ? stack_mem[SP-1] : 4'b0;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 3'b0;
            for (integer i = 0;
 i < 4;
 i = i + 1) begin
                stack_mem[i] <= 4'b0;
            end
        end else if (EN) begin
            if (!FULL && !RW) begin 
                stack_mem[SP] <= dataIn;
                SP <= SP + 1;
            end else if (!EMPTY && RW) begin 
                stack_mem[SP-1] <= 4'b0;
                SP <= SP - 1;
            end
        end
    end

endmodule

