module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

reg [1:0] state;
reg next_state;

localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10;


always @(*) begin
    case (state)
        S0: next_state = data_in ? S1 : S0;
        S1: next_state = (~data_in) ? S2 : S0;
        S2: next_state = S0;
        default: next_state = S0;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end


assign data_out = (state == S2) ? 1'b1 : 1'b0;

endmodule

