module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle      = 2'b00;
    parameter s1_red    = 2'b01;
    parameter s3_green  = 2'b10;
    parameter s2_yellow = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;


    always @(*) begin
        case (state)
            idle:       next_state = s1_red;
            s1_red:     next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green:   next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow:  next_state = (cnt == 0) ? s1_red : s2_yellow;
            default:    next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt   <= 8'd10;

        end else begin
            state <= next_state;
            if (state != next_state) begin

                case (next_state)
                    s1_red:    cnt <= 8'd10;

                    s3_green:  cnt <= 8'd60;

                    s2_yellow: cnt <= 8'd5;

                    default:   cnt <= cnt;

                endcase
            end else if (state == s3_green && pass_request) begin

                cnt <= (cnt > 8'd10) ? 8'd10 : cnt;
            end else begin
                cnt <= cnt - 1'b1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b000;
        end else begin
            case (state)
                s1_red:    {red, yellow, green} <= 3'b100;
                s3_green:  {red, yellow, green} <= 3'b001;
                s2_yellow: {red, yellow, green} <= 3'b010;
                default:   {red, yellow, green} <= 3'b000;
            endcase
        end
    end

    assign clock = cnt;

endmodule

