            quotient <= 0;
            remainder <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        dividend_sign <= sign ? dividend[7] : 0;
                        divisor_sign <= sign ? divisor[7] : 0;
                        abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                        abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;


                        SR <= {8'b0, abs_dividend} << 1;
                        cnt <= 1;
                        start_cnt <= 1;
                        state <= CALC;
                    end
                end

                CALC: begin
                    if (start_cnt) begin
                        if (cnt < 8) begin

                            reg [8:0] sub_result = SR[16:8] - abs_divisor;
                            if (sub_result[8]) begin 
                                SR[16:8] <= SR[16:8];

                                quotient <= {quotient[6:0], 1'b0};
                            end else begin
                                SR[16:8] <= sub_result[7:0];
                                quotient <= {quotient[6:0], 1'b1};
                            end
                            SR <= SR << 1;
                            cnt <= cnt + 1;
                        end else begin

                            remainder <= SR[16:9];
                            quotient <= {quotient[6:0], 1'b0};
                            start_cnt <= 0;
                            state <= ADJUST;
                        end
                    end
                end

                ADJUST: begin

                    if (sign) begin
                        quotient <= (dividend_sign ^ divisor_sign) ? (~quotient + 1) : quotient;
                        remainder <= dividend_sign ? (~remainder + 1) : remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                    state <= DONE;
                end

                DONE: begin
                    if (res_valid && !opn_valid) begin
                        res_valid <= 0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

