    reg [15:0] areg;

    reg [15:0] breg;

    reg [31:0] yout_r;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'b0;
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
            done <= 1'b0;
        end else begin

            if (start) begin
                if (i < 5'b10001) 
                    i <= i + 1'b1;
                else
                    i <= i;
            end else
                i <= 5'b0;


            if (i == 5'b0) begin
                areg <= ain;
                breg <= bin;
                yout_r <= 32'b0;
            end

            else if (i >= 5'b00001 && i <= 5'b10000) begin
                if (areg[i-1])
                    yout_r <= yout_r + (breg << (i-1));
            end


            if (i == 5'b10000) begin
                done <= 1'b1;
            end

            else if (i == 5'b10001) begin
                done <= 1'b0;
            end

            else
                done <= done;
        end
    end


    assign yout = yout_r;

