module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;

    reg [N:0] sum;

    reg res_sign;

    always @(*) begin
        if (sign_a == sign_b) begin

            sum = {1'b0, abs_a} + {1'b0, abs_b};
            res_sign = sign_a;
        end else begin

            if (abs_a > abs_b) begin
                sum = {1'b0, abs_a} - {1'b0, abs_b};
                res_sign = sign_a;
            end else if (abs_b > abs_a) begin
                sum = {1'b0, abs_b} - {1'b0, abs_a};
                res_sign = sign_b;
            end else begin
                sum = 0;
                res_sign = 0;
            end
        end
    end


    assign c = {res_sign, sum[N-1:0]};

endmodule

