module fixed_point_subtractor #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input  [N-1:0] a,  
    input  [N-1:0] b,  
    output [N-1:0] c   
);

    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-Q-1:0] int_a, int_b;
    reg [Q-1:0] frac_a, frac_b;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        int_a  = a[N-2 : N-Q-1];
        frac_a = a[Q-1 :0];
        int_b  = b[N-2 : N-Q-1];
        frac_b = b[Q-1 :0];

        if (sign_a == sign_b) begin

            res = {sign_a, (int_a - int_b), (frac_a - frac_b)};
        end else begin

            reg [N-Q-1:0] a_int_abs, b_int_abs;
            reg [Q-1:0] a_frac_abs, b_frac_abs;
            reg [N-Q-1:0] sum_int;
            reg [Q-1:0] sum_frac;
            reg sum_sign;


            a_int_abs = sign_a ? (~int_a + 1) : int_a;
            b_int_abs = sign_b ? (~int_b + 1) : int_b;
            a_frac_abs = frac_a;
            b_frac_abs = frac_b;


            sum_int = a_int_abs + b_int_abs;
            sum_frac = a_frac_abs + b_frac_abs;


            if (sum_frac >= (1 << Q)) begin
                sum_int += 1;
                sum_frac -= (1 << Q);
            end


            if (a_int_abs > b_int_abs || (a_int_abs == b_int_abs && a_frac_abs >= b_frac_abs)) begin
                sum_sign = sign_a;
            end else begin
                sum_sign = sign_b;
            end

            res = {sum_sign, sum_int, sum_frac};
        end


        if (res == 0) begin
            res = {1'b0, {(N-Q-1){1'b0}}, {Q{1'b0}}};
        end
    end

    assign c = res;

endmodule

