module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z_mantissa <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};

                    if (a[30:23] == 8'hff) begin
                        if (a[22:0] != 0) begin

                            z_sign <= a[31] ^ b[31];
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'h1;
                        end else if (b[30:23] == 8'hff) begin
                            if (b[22:0] != 0) begin

                                z_sign <= a[31] ^ b[31];
                                z_exponent <= 8'hff;
                                z_mantissa <= 23'h1;
                            end else begin

                                z_sign <= a_sign ^ b_sign;
                                z_exponent <= 8'hff;
                                z_mantissa <= 0;
                            end
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z_mantissa <= 0;
                        end
                    end else if (b[30:23] == 8'hff) begin
                        if (b[22:0] != 0) begin

                            z_sign <= a[31] ^ b[31];
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'h1;
                        end else begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z_mantissa <= 0;
                        end
                    end else if (a == 0 || b == 0) begin
                        if (a == 0 && b == 0) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'h1;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 0;
                            z_mantissa <= 0;
                        end
                    end else begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 10'd127;
                        product <= a_mantissa * b_mantissa;
                        counter <= 1;
                    end
                end
                1: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    if (product[47]) begin
                        z_mantissa <= product[46:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end else begin
                        z_mantissa <= product[47:25];
                        guard_bit <= product[24];
                        round_bit <= product[23];
                        sticky <= |product[22:0];
                    end
                    counter <= 2;
                end
                2: begin

                    if (guard_bit) begin
                        if (round_bit || sticky) begin
                            z_mantissa <= z_mantissa + 1;
                        end else if (z_mantissa[0]) begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    if (z_mantissa[23]) begin
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= z_mantissa >> 1;
                    end
                    counter <= 3;
                end
                3: begin

                    if (z_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 8'h0, z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

endmodule

